import {RULES,fixtures,detect,validateEvents,eventLabel,investigate,evaluate,exportBrief} from './engine.js';
const paths={bolt:'m13 2-9 12h7l-1 8 10-13h-7z',target:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 11v2',compass:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 m4 5-3 5-5 3 3-5z',checklist:'M9 5h12 M9 12h12 M9 19h12 M2 5l2 2 3-4 M2 12l2 2 3-4 M2 19l2 2 3-4',leaf:'M20 3C6 2 2 10 7 16s15 1 13-13 M4 21 16 9',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1.5 1.5 M17.5 17.5 1.5 1.5 M5 19l1.5-1.5 M17.5 6.5 1.5-1.5',moon:'M20.5 13A9 9 0 0 1 11 3.5 9 9 0 1 0 20.5 13z',palette:'M12 3a9 9 0 1 0 0 18h1a2 2 0 0 0 1-4c-1-1 0-3 2-3h2a3 3 0 0 0 3-3 9 9 0 0 0-9-8 M7 10h.01 M10 7h.01 M15 7h.01 M18 10h.01',bookmark:'M6 3h12v18l-6-4-6 4z',shield:'M12 3 21 7v6c0 5-9 9-9 9S3 18 3 13V7z M8 12l3 3 5-6',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',chevron:'m9 5 7 7-7 7',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',upload:'M12 16V4 m-5 5 5-5 5 5 M4 16v5h16v-5',activity:'M2 12h5l3-8 4 16 3-8h5',file:'M5 3h9l5 5v13H5z M14 3v6h5 M8 13h8 M8 17h6',sliders:'M4 3v7 m0 4v7 M12 3v11 m0 4v3 M20 3v3 m0 4v11 M1 10h6 M9 14h6 M17 6h6',flask:'M9 3h6 M10 3v6L4 19q-1 2 2 2h12q3 0 2-2L14 9V3 M7 15h10',lock:'M6 10h12v11H6z M8 10V7a4 4 0 0 1 8 0v3 M12 14v3',check:'m5 12 4 4L19 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-3c0-6 16-6 16 0v3',server:'M3 3h18v7H3z M3 14h18v7H3z M6 6h.01 M6 17h.01 M10 6h8 M10 17h8',arrow:'M5 12h14 m-5-5 5 5-5 5',close:'m6 6 12 12 M6 18 18 6',menu:'M3 6h18 M3 12h18 M3 18h18',play:'m8 4 12 8-12 8z',code:'m8 7-5 5 5 5 M16 7l5 5-5 5 M14 3l-4 18',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M9 8c0-4 7-4 7 0 0 3-4 2-4 6 M12 17h.01',refresh:'M20 7v5h-5 M4 17v-5h5 M5 7a8 8 0 0 1 14-1l1 6 M4 12l1 6a8 8 0 0 0 14-1',chart:'M4 3v18h17 M8 16v-5 M13 16V6 M18 16V9',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7 M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3z M12 6v16'};
Object.assign(paths,{sparkles:'M12 2l1.4 5.1L18 9l-4.6 1.9L12 16l-1.4-5.1L6 9l4.6-1.9z M19 15l.8 2.2L22 18l-2.2.8L19 21l-.8-2.2L16 18l2.2-.8z M5 16l.7 1.7L7.5 18l-1.8.7L5 20.5l-.7-1.8L2.5 18l1.8-.7z',layers:'M12 3 3 8l9 5 9-5-9-5 M3 12l9 5 9-5 M3 16l9 5 9-5',database:'M4 6c0-2 3.6-3 8-3s8 1 8 3-3.6 3-8 3-8-1-8-3 M4 6v6c0 2 3.6 3 8 3s8-1 8-3V6 M4 12v6c0 2 3.6 3 8 3s8-1 8-3v-6',radar:'M12 3a9 9 0 1 0 9 9 M12 7a5 5 0 1 0 5 5 M12 11a1 1 0 1 0 1 1 M12 3v8l6 3'});
const icon=(name)=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.shield}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=t=>new Date(t).toISOString().slice(11,16);
const badge=(s)=>`<span class="badge ${s.toLowerCase()}">${esc(s[0].toUpperCase()+s.slice(1))}</span>`;
const btn=(text,action,ico='',primary=false,extra='')=>`<button class="btn ${primary?'primary':''}" data-action="${action}" ${extra}>${ico?icon(ico):''}${text}</button>`;
const titles={overview:'Overview',alerts:'Alert inbox',logs:'Event explorer',rules:'Detection rules',lab:'Scenario lab',evaluations:'Evaluation lab',privacy:'Privacy & security',guide:'Field guide',detail:'Investigation',profile:'My profile',saved:'Saved investigations'};
let events=fixtures(),enabled=new Set(RULES.map(r=>r.id)),alerts=detect(events),view='overview',selected=null,filter='',severity='all',statusFilter='all',logType='all',logPage=0,mask=true,evaluations=null,activeTab='controls';
let profile={name:'Lab Analyst',role:'Security researcher',bio:'Following the evidence. Building a safer digital world.',color:'amethyst',theme:'daylight',accent:'amethyst',compact:false};
const bookmarks=new Set();
let dashboardFocus='open';
let workspaceRole='Owner';
const bookmarkKey=a=>[a.ruleId,a.account,a.ip].join('|');
const isSaved=a=>bookmarks.has(bookmarkKey(a));
const initials=()=>profile.name.trim().split(/\s+/).map(w=>Array.from(w)[0]).slice(0,2).join('').toUpperCase()||'LA';
const avatar=(extra='')=>`<div class="avatar ${extra}" data-color="${profile.color}">${esc(initials())}</div>`;
const audit=[{at:new Date().toISOString(),text:'Local portfolio lab initialized; synthetic workspace not yet entered.'}];
function log(text){audit.unshift({at:new Date().toISOString(),text});if(audit.length>200)audit.pop();}
function toast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3600);}
const address=ip=>mask?ip.split('.').slice(0,3).join('.')+'.••':ip;
function rerun(){const old=new Map(alerts.map(a=>[`${a.ruleId}:${a.account}:${a.ip}`,a]));alerts=detect(events,enabled).map(a=>({...a,...(old.has(`${a.ruleId}:${a.account}:${a.ip}`)?{status:old.get(`${a.ruleId}:${a.account}:${a.ip}`).status,notes:old.get(`${a.ruleId}:${a.account}:${a.ip}`).notes,report:old.get(`${a.ruleId}:${a.account}:${a.ip}`).report}: {})}));}
function navigate(next){document.querySelector('#dialog').close();view=next;filter='';severity='all';statusFilter='all';logPage=0;render();window.scrollTo(0,0);document.querySelector('#main').focus({preventScroll:true});}
function sidebar(){
 const nav=(id,ico,count='')=>`<button data-nav="${id}" class="${view===id||id==='alerts'&&view==='detail'?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ico)}${titles[id]}${count!==''?`<span class="count">${count}</span>`:''}</button>`;
 return `<aside class="sidebar"><div class="brand">${icon('shield')}TraceGuard<span>LAB</span><button class="sidebar-close" data-action="menu" aria-label="Close navigation">${icon('close')}</button></div>
 <div class="sidebar-scroll"><div class="workspace">${icon('server')}<div>TraceGuard workspace<small class="muted workspace-subtitle">Security operations</small></div><span class="workspace-dot" aria-hidden="true"></span></div>
 <p class="navlabel">WORKSPACE</p><nav class="nav" aria-label="Workspace">${nav('overview','grid')}${nav('alerts','bell',alerts.filter(a=>a.status!=='Resolved').length)}${nav('logs','activity')}${nav('saved','bookmark',alerts.filter(isSaved).length)}${nav('rules','sliders')}</nav>
 <div class="divider"></div><p class="navlabel">BUILD & VALIDATE</p><nav class="nav" aria-label="Lab tools">${nav('lab','flask')}${nav('evaluations','chart')}${nav('privacy','lock')}${nav('guide','book')}</nav></div>
 <div class="sidebar-bottom"><button class="profile" data-nav="profile" aria-label="Open my profile">${avatar()}<div>${esc(profile.name)}<small>${esc(profile.role)}</small></div>${icon('chevron')}</button>
 <div class="sidebar-appearance"><span class="appearance-label">${icon('palette')} Appearance</span><div class="theme-switch" role="group" aria-label="Website appearance"><button data-theme="daylight" aria-pressed="${profile.theme==='daylight'}">${icon('sun')}Light</button><button data-theme="midnight" aria-pressed="${profile.theme==='midnight'}">${icon('moon')}Dark</button></div></div>
 <span class="sidebar-session">${icon('lock')} Private, session-only lab</span></div></aside>`;
}
function render(){document.documentElement.dataset.theme=profile.theme;document.documentElement.dataset.accent=profile.accent;document.body.classList.toggle('compact',profile.compact);document.querySelector('#app').innerHTML=`<div class="layout">${sidebar()}<div class="page"><header class="topbar"><div class="breadcrumb"><button class="mobile-menu" aria-label="Toggle navigation" data-action="menu">${icon('menu')}</button><span>Workspace</span><span>/</span><strong>${titles[view]}</strong></div><div class="top-actions"><button class="quick-launch" data-action="quick-actions" aria-label="Open quick actions">${icon('bolt')}<span>Quick actions</span></button><button class="search-launch" data-action="search">${icon('search')}Search alerts <kbd>Ctrl K</kbd></button><span class="pill green"><span class="dot"></span>Synthetic lab</span><button class="icon-button" data-action="activity-panel" aria-label="Workspace activity">${icon('bell')}</button><button class="profile-trigger" data-nav="profile" aria-label="Open my profile">${avatar()}</button></div></header><main class="main" id="main" tabindex="-1">${({overview,alerts:inbox,logs:logsView,rules:rulesView,lab:labView,evaluations:evalView,privacy:privacyView,guide:guideView,detail:detailView,profile:profileView,saved:savedView}[view])()}<footer class="footer"><span>${icon('lock')}Session-only data · No model connection</span><span>TraceGuard / Security investigation lab <span class="mono">v0.1</span></span></footer></main></div></div>`;applyStyles();}
function applyStyles(){// Dynamic chart geometry is applied through the CSSOM, never from imported strings.
 document.querySelectorAll('[data-height]').forEach(e=>{e.style.height=Number(e.dataset.height)+'%';});
 const d=document.querySelector('[data-donut]');if(d){let total=alerts.length||1,angle=0;const theme=getComputedStyle(document.documentElement);const colors={critical:theme.getPropertyValue('--pink').trim(),high:theme.getPropertyValue('--amber').trim(),medium:theme.getPropertyValue('--accent').trim(),low:theme.getPropertyValue('--cyan').trim()};const segments=Object.entries(colors).map(([s,c])=>{let start=angle;angle+=alerts.filter(a=>a.severity===s).length/total*360;return `${c} ${start}deg ${angle}deg`;});d.style.background=alerts.length?`conic-gradient(${segments.join(',')})`:'var(--line)';}}
function heading(title,desc,actions=''){return `<div class="heading"><div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;}
function banner(){const open=alerts.filter(a=>a.status!=='Resolved');return `<section class="command-banner"><div class="command-copy"><span class="eyebrow">${icon('compass')} A CLEARER VIEW OF SECURITY</span><h2>Every signal has a story.<br><span>Find the one that matters.</span></h2><p>Your space to investigate, connect the evidence, and build confidence.</p><div class="hero-actions">${btn(open.length?'Start next investigation':'Explore your workspace',open.length?'next-case':'lab','arrow',true)}<span>${icon('lock')}Synthetic data. Your session.</span></div></div><div class="signal-art" aria-hidden="true"><div class="signal-orbit orbit-one"></div><div class="signal-orbit orbit-two"></div><div class="signal-core">${icon('shield')}</div><span class="signal-node node-a">${icon('activity')}</span><span class="signal-node node-b">${icon('lock')}</span><span class="signal-node node-c">${icon('check')}</span><span class="signal-caption">EVIDENCE → CLARITY</span></div></section>`;}
function focusFilters(){return `<div class="focus-filters" role="group" aria-label="Dashboard alert focus">${[['open','bell','Open'],['critical','target','Critical'],['saved','bookmark','Saved']].map(([id,ico,label])=>`<button data-focus="${id}" aria-pressed="${dashboardFocus===id}">${icon(ico)}${label}<span>${alerts.filter(a=>id==='saved'?isSaved(a):a.status!=='Resolved'&&(id==='open'||a.severity==='critical')).length}</span></button>`).join('')}</div>`;}
function focusedAlerts(){return alerts.filter(a=>dashboardFocus==='saved'?isSaved(a):a.status!=='Resolved'&&(dashboardFocus==='open'||a.severity==='critical'));}
function sessionJourney(){const briefs=alerts.filter(a=>a.report).length;const resolved=alerts.filter(a=>a.status==='Resolved').length;const checks=evaluations?.filter(x=>x.pass).length||0;const steps=[['file','Create an evidence brief',`${briefs} created`,briefs>0,'next-case'],['check','Review a case',`${resolved} resolved`,resolved>0,'alerts'],['flask','Validate the rules',`${checks} checks passed`,checks>0,'evaluations']];return `<section class="journey-card"><div class="journey-intro"><span class="eyebrow">YOUR SESSION</span><h2>${icon('compass')}A little progress, every day.</h2><p>${steps.filter(x=>x[3]).length} of 3 milestones completed</p></div><div class="journey-steps">${steps.map(([ico,title,sub,done,action])=>`<button data-action="${action}" class="journey-step ${done?'complete':''}"><span class="journey-icon">${icon(done?'check':ico)}</span><span><strong>${title}</strong><small>${sub}</small></span>${icon('chevron')}</button>`).join('')}</div></section>`;}
function metrics(){const list=[['Events analyzed',events.length.toLocaleString(),'activity','In the current lab dataset'],['Open alerts',alerts.filter(a=>a.status!=='Resolved').length,'bell',`${alerts.filter(a=>a.severity==='critical'&&a.status!=='Resolved').length} critical · awaiting review`],['Active detections',enabled.size,'shield','Of 3 configured rules'],['Cases resolved',alerts.filter(a=>a.status==='Resolved').length,'check','Reviewed in this session']];return `<div class="metrics">${list.map(([label,n,ico,sub],i)=>`<div class="metric"><div class="metric-top">${label}${icon(ico)}</div><div class="metric-value">${n}</div><div class="metric-bottom">${sub}</div></div>`).join('')}</div>`;}
function chart(){let buckets=Array.from({length:Math.max(12,...events.map(e=>new Date(e.timestamp).getUTCHours()+1))},(_,h)=>({h,n:0,f:0}));events.forEach(e=>{const h=new Date(e.timestamp).getUTCHours();if(h<buckets.length){buckets[h].n++;if(e.type==='login_failed')buckets[h].f++;}});let max=Math.max(1,...buckets.map(b=>b.n));return `<div class="card"><div class="card-head"><div><h2>${icon('activity')}Authentication activity</h2><small>Events grouped by hour · UTC · current dataset</small></div><div class="legend"><span><i></i>Events</span><span><i></i>Failures</span></div></div><div class="card-body"><div class="chart" role="img" aria-label="Hourly event counts: ${buckets.map(b=>`${b.h}:00 ${b.n} events, ${b.f} failures`).join('; ')}"><div class="y-axis"><span>${max}</span><span>${Math.round(max/2)}</span><span>0</span></div><div class="plot">${buckets.map(b=>`<div class="bar-group" title="${b.h}:00 · ${b.n} events / ${b.f} failures"><i data-height="${b.n/max*90}"></i><i class="alertbar" data-height="${b.f/max*90}"></i><span>${String(b.h).padStart(2,'0')}</span></div>`).join('')}</div></div></div></div>`;}
function risk(){return `<div class="card"><div class="card-head"><div><h2>Alert distribution</h2><small>Rule-assigned severity</small></div>${icon('chart')}</div><div class="risk-body"><div class="donut" data-donut><div class="donut-inner"><strong>${alerts.length}</strong><span>Total alerts</span></div></div><div class="risk-legend">${['critical','high','medium','low'].map(s=>`<div><i class="swatch ${s}"></i>${s[0].toUpperCase()+s.slice(1)}<b>${alerts.filter(a=>a.severity===s).length}</b></div>`).join('')}</div></div></div>`;}
function alertTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Alert / account</th><th>Severity</th><th>Status</th><th>Detected UTC</th><th></th></tr></thead><tbody>${rows.map(a=>`<tr><td><div class="alert-name"><div class="alert-icon">${icon(a.ruleId==='TG-003'?'user':'shield')}</div><button data-open="${a.id}">${esc(a.title)}<small><span class="mono">${a.id}</span> · ${esc(a.account)}</small></button></div></td><td>${badge(a.severity)}</td><td>${badge(a.status)}</td><td class="mono">${time(a.time)}</td><td><button class="text-btn" data-open="${a.id}" aria-label="Investigate ${a.id}">Investigate ${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('check')}<h3>No matching alerts</h3><p>Change your filters or load a lab scenario.</p></div>`;}
function overview(){return heading('Security overview',`Welcome back, ${esc(profile.name)}. Here’s your workspace at a glance.`,btn('Import lab events','import','upload')+btn('Open scenario lab','lab','flask',true))+banner()+metrics()+`<div class="row">${chart()}${risk()}</div><section class="card"><div class="card-head"><div><h2>${icon('bell')}Priority alerts <span class="muted">/ ${alerts.filter(a=>a.status!=='Resolved').length}</span></h2><small>Review the highest-severity signals first</small></div><button class="text-btn" data-nav="alerts">View all alerts ${icon('chevron')}</button></div>${focusFilters()}${focusedAlerts().length?alertTable(focusedAlerts().slice(0,4)):'<div class="focus-empty">'+icon('bookmark')+'<p>No '+(dashboardFocus==='saved'?'saved investigations':'matching open alerts')+' yet.</p><button class="text-btn" data-nav="alerts">Browse the alert inbox '+icon('arrow')+'</button></div>'}<div class="table-footer"><span>Detection is a signal, not a verdict.</span><span>Sorted by severity · ${focusedAlerts().length} in this view</span></div></section>${sessionJourney()}<div class="bottom-row"><section class="card"><div class="card-head"><h2>${icon('clock')}Workspace activity</h2><button class="text-btn" data-action="audit">View audit log ${icon('chevron')}</button></div><div class="card-body">${audit.slice(0,3).map(a=>`<div class="event"><div class="event-icon">${icon('check')}</div><div>${esc(a.text)}<small>Local session activity</small></div><time>${time(a.at)} UTC</time></div>`).join('')}</div></section><section class="card"><div class="card-head"><h2>${icon('lock')}Data & protection</h2><span class="pill">Lab environment</span></div><div class="card-body"><div class="source">${icon('server')}<div><strong>Identity event fixture</strong><small>${events.length} synthetic events · no live connection</small></div><span class="badge resolved">Synthetic</span></div><div class="source">${icon('lock')}<div><strong>External AI services</strong><small>No prompts or logs sent to a model</small></div><span class="badge new">Disconnected</span></div><div class="source">${icon('eye')}<div><strong>Address display</strong><small>Documentation-only IP addresses</small></div><span class="badge resolved">${mask?'Masked':'Visible'}</span></div></div></section></div>`;}
function savedView(){const rows=alerts.filter(isSaved);return heading('Saved investigations','Keep the cases you want to revisit close at hand. Bookmarks stay in this session.',btn('Browse alerts','alerts','bell'))+`<section class="card"><div class="card-head"><h2>${icon('bookmark')}Your watchlist</h2><span class="pill">${rows.length} saved</span></div>${rows.length?alertTable(rows):'<div class="empty">'+icon('bookmark')+'<h3>Your next investigation starts here</h3><p>Open any alert and choose “Save investigation” to add it to your watchlist.</p></div>'}</section>`;}
function inbox(){const rows=alerts.filter(a=>(severity==='all'||a.severity===severity)&&(statusFilter==='all'||a.status===statusFilter)&&`${a.title} ${a.id} ${a.account}`.toLowerCase().includes(filter.toLowerCase()));return heading('Alert inbox','Turn a security signal into an evidence-backed decision.',btn('Export alert summary','export-alerts','download'))+`<section class="card"><div class="toolbar"><input class="field search-field" id="alert-search" placeholder="Search alerts, accounts, or IDs…" aria-label="Search alerts" value="${esc(filter)}"><select class="field" id="severity" aria-label="Filter severity">${['all','critical','high','medium','low'].map(s=>`<option value="${s}" ${s===severity?'selected':''}>${s==='all'?'All severities':s[0].toUpperCase()+s.slice(1)}</option>`).join('')}</select><select class="field" id="status-filter" aria-label="Filter status">${['all','New','Investigating','Resolved'].map(s=>`<option value="${s}" ${s===statusFilter?'selected':''}>${s==='all'?'All statuses':s}</option>`).join('')}</select></div>${alertTable(rows)}<div class="table-footer"><span>${rows.length} of ${alerts.length} alerts</span><span>All timestamps in UTC</span></div></section>`;}
function logsView(){const rows=events.filter(e=>(logType==='all'||e.type===logType)&&`${e.id} ${e.account} ${e.type}`.toLowerCase().includes(filter.toLowerCase())).reverse();const pages=Math.max(1,Math.ceil(rows.length/20));logPage=Math.min(logPage,pages-1);return heading('Event explorer','Inspect the original signals behind every investigation.',btn('Download sample','sample','download')+btn('Import lab events','import','upload',true))+`<section class="card"><div class="toolbar"><input class="field search-field" id="log-search" value="${esc(filter)}" aria-label="Search events" placeholder="Search event ID, account, or type…"><select class="field" id="log-type" aria-label="Filter event type">${['all','login_failed','login_success','role_changed','session_ended'].map(s=>`<option value="${s}" ${s===logType?'selected':''}>${s==='all'?'All event types':eventLabel(s)}</option>`).join('')}</select><button class="btn" data-action="mask">${icon('eye')}${mask?'Reveal lab IPs':'Mask addresses'}</button></div><div class="table-wrap"><table><thead><tr><th>Time UTC</th><th>Event ID</th><th>Event</th><th>Account</th><th>Source IP</th></tr></thead><tbody>${rows.slice(logPage*20,logPage*20+20).map(e=>`<tr><td class="mono">${time(e.timestamp)}</td><td class="mono">${esc(e.id)}</td><td>${eventLabel(e.type)}</td><td>${esc(e.account)}</td><td class="mono">${esc(address(e.ip))}</td></tr>`).join('')}</tbody></table></div>${!rows.length?'<div class="empty">No matching events. Try another search.</div>':''}<div class="table-footer"><span>${rows.length} events · page ${logPage+1} of ${pages}</span><div class="actions">${btn('Previous','prev','','',logPage===0?'disabled':'')}${btn('Next','next','','',logPage>=pages-1?'disabled':'')}</div></div></section>`;}
function detailView(){const a=alerts.find(x=>x.id===selected);if(!a){view='alerts';return inbox();}const evidence=events.filter(e=>a.evidence.includes(e.id));return heading(esc(a.title),`${a.id} · ${a.account} · ${a.ruleId}`,btn('Back to inbox','alerts')+btn(isSaved(a)?'Saved':'Save investigation','bookmark','bookmark',false,`aria-pressed="${isSaved(a)}"`)+btn('Export report','export-report','download',false,!a.report?'disabled':''))+`<div class="detail-meta">${badge(a.severity)}${badge(a.status)}<span class="pill">${evidence.length} evidence events</span><span class="pill">${esc(RULES.find(r=>r.id===a.ruleId).mitre)}</span></div><div class="split row-gap"><div><section class="card"><div class="card-head"><div><h2>${icon('activity')}Evidence timeline</h2><small>${esc(a.time.slice(0,10))} · UTC · source: identity-lab</small></div>${icon('activity')}</div><div class="timeline">${evidence.map(e=>`<article class="timeline-item" id="${e.id}"><time>${time(e.timestamp)}:${new Date(e.timestamp).toISOString().slice(17,19)} UTC</time><h3>${eventLabel(e.type)}</h3><p>${esc(e.account)} · <span class="mono">${esc(address(e.ip))}</span></p><span class="evidence-id">${esc(e.id)}</span></article>`).join('')}</div></section><section class="card row-gap"><div class="card-head"><h2>${icon('file')}Analyst notes</h2><span class="pill">Session only</span></div><div class="card-body"><p class="subtle">Use lab observations only. Notes stay in memory and are excluded from exports.</p><label class="inline-label" for="note">Investigation note</label><textarea class="field note" id="note" maxlength="1000" placeholder="What did you observe? What needs verification?"></textarea><div class="actions row-gap">${btn('Add note','note','file')}</div>${a.notes.map(n=>`<div class="note-entry"><small>${time(n.at)} UTC · Analyst</small>${esc(n.text)}</div>`).join('')}</div></section></div><div><section class="card"><div class="card-head"><div><h2>${icon('shield')}Investigation brief</h2><small>Trace every conclusion to the source</small></div>${icon('shield')}</div><div class="card-body"><div class="report-stamp">Rules-based preview · no language model connected</div>${a.report?reportHTML(a.report):`<div class="empty">${icon('file')}<h3>Let the evidence lead</h3><p>Create a structured brief from this alert’s supporting events.</p></div>${btn('Generate investigation brief','investigate','play',true)}`}<p class="subtle">No account changes are made. Every response remains a human decision.</p></div></section><section class="card row-gap"><div class="card-head"><h2>${icon('checklist')}Case disposition</h2></div><div class="card-body"><label for="case-status" class="inline-label">Review status</label><select class="field status-select" id="case-status">${['New','Investigating','Resolved'].map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select><p class="subtle">“Resolved” records your review; it does not remediate an account.</p></div></section></div></div>`;}
function reportHTML(r){return `<div class="report"><h3>Assessment</h3><p>${esc(r.summary)}</p><h3>Observed evidence</h3><ul>${r.observations.map(o=>`<li>${esc(mask?o.text.replace(/(?:192\.0\.2|198\.51\.100|203\.0\.113)\.\d+/g,address):o.text)} <a href="#${o.id}">${o.id}</a></li>`).join('')}</ul><div class="callout"><strong>What we cannot conclude</strong><ul>${r.gaps.map(g=>`<li>${g}</li>`).join('')}</ul></div><h3>Recommended review</h3><ol>${r.steps.map(s=>`<li>${s}</li>`).join('')}</ol></div>`;}
function rulesView(){return heading('Detection rules','Transparent logic. Predictable behavior. A baseline you can test.',btn('Run evaluations','evaluations','chart',true))+`<div class="banner">${icon('help')}<div>Rule changes reprocess the current dataset. Disabling a rule removes its alerts and their session notes.</div></div><section class="card">${RULES.map(r=>`<article class="rule"><div class="rule-icon">${icon('shield')}</div><div><span class="eyebrow">${r.id} · ${r.mitre}</span><h2>${r.name}</h2><p>${r.description}</p><code>${esc(r.logic)}</code><div class="detail-meta">${badge(r.severity)}<span class="pill">${alerts.filter(a=>a.ruleId===r.id).length} matches</span></div></div><button class="switch" role="switch" aria-checked="${enabled.has(r.id)}" aria-label="Enable ${r.name}" data-rule="${r.id}"></button></article>`).join('')}</section><div class="notice">Technique mappings are investigation context, not proof of an attack. These rules cover a small identity-event lab; they are not a complete detection system.</div>`;}
function labView(){const scenarios=[['takeover','shield','Account takeover pattern','Repeated failed sign-ins, a successful authentication, and an administrator role assignment.','11 events · three detection types'],['brute','lock','Password guessing pattern','A burst of failed authentication attempts for a simulated service account.','8 events · one detection type'],['privilege','user','Privileged access change','An administrator role assignment that requires a change-approval check.','1 event · one detection type'],['normal','activity','Everyday activity','Successful sign-ins and session endings. A baseline for checking false alerts.','128 events · no expected alerts']];return heading('Scenario lab','Reproducible scenarios. No real accounts, attacks, or connected systems.',btn('Restore full demo','reset','refresh'))+`<div class="grid3">${scenarios.map(([id,ico,title,desc,sub])=>`<article class="card feature-card">${icon(ico)}<span class="tag eyebrow">IDENTITY LAB</span><h2>${title}</h2><p>${desc}</p><p class="mono">${sub}</p>${btn('Load scenario',`scenario:${id}`,'play',true)}</article>`).join('')}<article class="card feature-card">${icon('code')}<span class="tag eyebrow">YOUR FIXTURE</span><h2>Bring a synthetic dataset</h2><p>Download the schema example, edit its lab values, and test your own event sequences.</p><div class="actions">${btn('Get sample','sample','download')}${btn('Import','import','upload')}</div></article><article class="card feature-card">${icon('chart')}<span class="tag eyebrow">QUALITY CHECK</span><h2>Test the boundaries</h2><p>Verify thresholds, time windows, source separation, event ordering, and normal activity.</p>${btn('Open evaluations','evaluations','chart')}</article></div>`;}
function evalView(){const pass=evaluations?.filter(x=>x.pass).length||0;return heading('Evaluation lab','Measure the detection engine against explicit, repeatable expectations.',btn('Run test suite','run-evals','play',true))+`<div class="banner">${icon('flask')}<div>These are synthetic functional tests, not a production accuracy benchmark or an AI evaluation.</div></div>${evaluations?`<div class="metrics"><div class="metric"><div class="metric-top">Tests passed</div><div class="metric-value">${pass} / ${evaluations.length}</div><div class="metric-bottom">Executed in your browser</div></div><div class="metric"><div class="metric-top">Detection rules tested</div><div class="metric-value">3</div><div class="metric-bottom">All baseline rules enabled for tests</div></div><div class="metric"><div class="metric-top">Failed expectations</div><div class="metric-value">${evaluations.length-pass}</div><div class="metric-bottom">Compare expected and observed</div></div><div class="metric"><div class="metric-top">AI evaluations</div><div class="metric-value">—</div><div class="metric-bottom">No model is connected</div></div></div><section class="card"><div class="card-head"><h2>${icon('checklist')}Test results</h2>${btn('Export results','export-evals','download')}</div><div class="table-wrap"><table class="test-grid"><thead><tr><th>Scenario</th><th>Expected rules</th><th>Observed rules</th><th>Result</th></tr></thead><tbody>${evaluations.map(r=>`<tr><td>${r.name}</td><td class="mono">${r.expected.join(', ')||'No alerts'}</td><td class="mono">${r.actual.join(', ')||'No alerts'}</td><td>${badge(r.pass?'Passed':'critical')}</td></tr>`).join('')}</tbody></table></div></section>`:`<section class="card"><div class="empty">${icon('flask')}<h3>Evidence starts with testing</h3><p>Run 12 checks against the same engine that powers your alert inbox.</p><div class="actions row-gap centered">${btn('Run test suite','run-evals','play',true)}</div></div></section>`}`;}
function privacyView(){return heading('Privacy & security','Know what this workspace stores, sends, and cannot yet protect.',btn('Clear session data','clear','refresh'))+`<div class="tabs"><button class="${activeTab==='controls'?'active':''}" data-tab="controls">${icon('sliders')} Data controls</button><button class="${activeTab==='audit'?'active':''}" data-tab="audit">${icon('clock')} Session audit log</button></div>${activeTab==='audit'?`<section class="card"><div class="card-head"><h2>Session audit log</h2><span class="pill">${audit.length} entries</span></div>${audit.map(a=>`<div class="audit"><time>${time(a.at)} UTC</time><span>${esc(a.text)}</span></div>`).join('')}</section><p class="subtle">This in-memory activity log is editable through developer tools. It is not a tamper-proof compliance audit.</p>`:`<div class="split"><section class="card"><div class="card-head"><h2>Implemented in this demo</h2>${icon('lock')}</div>${[['Customer system connections','No live integrations or background collectors.','Disconnected'],['AI provider access','No model API, telemetry, or analytics calls in the app.','Disconnected'],['Workspace storage','Events, notes, and decisions exist only in tab memory.','Session only'],['Synthetic import validation','Fixed fields, demo account names, and documentation IP ranges.','Enforced'],['Import limits','Maximum 1 MB and 2,000 events per file.','Enforced'],['Export minimization','Reports exclude analyst notes and replace source IPs.','Enforced']].map(([title,desc,state])=>`<div class="privacy-row"><div><strong>${title}</strong><p>${desc}</p></div><span class="badge resolved">${state}</span></div>`).join('')}<div class="privacy-row"><div><strong>Mask source addresses</strong><p>Changes display only; all built-in addresses are synthetic.</p></div><button class="switch" role="switch" aria-checked="${mask}" aria-label="Mask source addresses" data-action="mask"></button></div></section><section class="card"><div class="card-head"><h2>Before using customer data</h2></div><div class="card-body"><p class="muted">This is a portfolio lab, not an approved customer-data environment.</p><ul class="check-list row-gap">${['Add authenticated backend access and tenant isolation.','Enforce permissions on every server request.','Configure encryption, key management, and retention.','Create a reviewed data-processing policy for any AI provider.','Complete security testing, monitoring, and an independent review.'].map(t=>`<li>${icon('lock')}<span>${t}</span></li>`).join('')}</ul><div class="notice">Import validation cannot prove that content is non-sensitive. Use generated lab data only. Downloaded exports remain on your device; clearing this session does not delete those files. The hosting provider may keep normal access logs.</div></div></section></div>`}`;}
function guideView(){return heading('Field guide','Understand the system well enough to explain every decision.')+`<div class="split"><section class="card"><div class="card-head"><h2>${icon('compass')}Your first investigation</h2></div><div class="card-body report"><ol><li>Open the <strong>Scenario lab</strong> and load the account takeover pattern.</li><li>In the <strong>Alert inbox</strong>, open the critical successful-login alert.</li><li>Read the evidence timeline and generate an investigation brief.</li><li>Distinguish recorded observations from possible explanations.</li><li>Add a lab note, choose a disposition, and export a redacted report.</li><li>Run the <strong>Evaluation lab</strong> and inspect the rule boundary tests.</li></ol>${btn('Start in the lab','lab','flask',true)}</div></section><section class="card"><div class="card-head"><h2>${icon('code')}How this version works</h2></div><div class="card-body report"><h3>Browser workspace</h3><p>The hosted demo runs its deterministic rules in your browser. Imported lab events are not uploaded. Reloading clears your changes.</p><h3>Python + SQL foundation</h3><p>The source repository includes a separate Python detection engine and SQLite lab store. It is not connected to the hosted demo.</p><h3>AI is the next milestone</h3><p>This version has no language-model integration. A future agent should use scoped read-only tools, cite events, and be evaluated against this baseline.</p><h3>Known limits</h3><p>Alerts are grouped once per rule, account, and IP for the current dataset. Repeated incidents may require session segmentation. Only one documented event format is supported.</p></div></section></div>`;}

const profileRoleOptions=['Security researcher','Student developer','Security analyst','Software engineer','Owner','Lab assistant'];
function saveProfileDraft(){if(view!=='profile')return;const name=document.querySelector('#profile-name')?.value.trim();if(name&&Array.from(name).length<=40)profile.name=name;const role=document.querySelector('#profile-role')?.value;if(profileRoleOptions.includes(role))profile.role=role;const bio=document.querySelector('#profile-bio')?.value;if(bio!==undefined)profile.bio=bio.trim().slice(0,180);}
function profileView(){const resolved=alerts.filter(a=>a.status==='Resolved').length;const briefs=alerts.filter(a=>a.report).length;return heading('Your profile','Make this workspace yours. Profile details stay in this tab.')+`<div class="profile-layout"><div><section class="card identity-card"><div class="identity-cover"></div>${avatar('identity-avatar')}<h2>${esc(profile.name)}</h2><p class="identity-role">${esc(profile.role)}</p><p class="identity-bio">${esc(profile.bio)||'Add a few words about your work.'}</p><span class="pill">${icon('flask')} Local lab profile</span><div class="profile-stats"><div><strong>${briefs}</strong><small>Briefs created</small></div><div><strong>${resolved}</strong><small>Cases resolved</small></div><div><strong>${evaluations?.filter(x=>x.pass).length||0}</strong><small>Checks passed</small></div></div></section><section class="card watchlist-card row-gap"><div class="card-head"><h2>${icon('bookmark')}Your watchlist</h2><span class="pill">${alerts.filter(isSaved).length} saved</span></div><div class="card-body"><p class="subtle">Return to the investigations that matter to you.</p>${btn('Open saved investigations','saved','bookmark')}</div></section><div class="profile-mini-note">${icon('lock')}<span>This is a session profile, not a login account. No email, password, or personal photo is collected. Reloading resets your changes.</span></div></div><div><section class="card profile-editor"><div class="card-head"><div><h2>Profile details</h2><small>A name and a little personality</small></div>${icon('user')}</div><div class="card-body"><div class="form-grid"><div class="form-field"><label for="profile-name">${icon('user')}Display name</label><input class="field" id="profile-name" value="${esc(profile.name)}" maxlength="40" autocomplete="off" placeholder="Choose a lab alias"></div><div class="form-field"><label for="profile-role">${icon('shield')}Role</label><select class="field" id="profile-role">${profileRoleOptions.map(r=>`<option ${profile.role===r?'selected':''}>${r}</option>`).join('')}</select></div><div class="form-field wide"><label for="profile-bio">${icon('file')}About you · 180 characters maximum</label><textarea class="field" id="profile-bio" maxlength="180" placeholder="Your interests, your focus, your next big idea…">${esc(profile.bio)}</textarea></div><div class="form-field wide"><span class="accent-label">Avatar color</span><div class="accent-options" role="group" aria-label="Avatar color">${['raspberry','graphite','jade','petal'].map(c=>`<button class="color-dot ${c}" data-avatar="${c}" aria-label="${c} avatar" aria-pressed="${profile.color===c}"></button>`).join('')}</div></div></div><div id="profile-error" class="error" role="alert"></div><div class="form-actions"><p>Use a lab alias. Saved only for this session.</p>${btn('Save profile','save-profile','check',true)}</div></div></section><section class="card row-gap"><div class="card-head"><div><h2>Appearance</h2><small>Your preferred way to investigate</small></div>${icon('palette')}</div><div class="card-body"><div class="appearance-options" role="group" aria-label="Color theme"><button class="theme-tile" data-theme="midnight" aria-pressed="${profile.theme==='midnight'}">${icon('moon')}Dark</button><button class="theme-tile" data-theme="daylight" aria-pressed="${profile.theme==='daylight'}">${icon('sun')}Light</button></div><div class="preference-row"><div><h3>Accent color</h3><p>A little color, throughout your workspace.</p></div><div class="accent-options" role="group" aria-label="Accent color">${['raspberry','graphite','jade'].map(c=>`<button class="palette-choice ${c}" data-accent="${c}" aria-label="${c} accent" aria-pressed="${profile.accent===c}"><span class="palette-swatch"></span>${c[0].toUpperCase()+c.slice(1)}</button>`).join('')}</div></div><div class="preference-row"><div><h3>Compact tables</h3><p>Fit more evidence on your screen.</p></div><button class="switch" role="switch" aria-label="Compact tables" aria-checked="${profile.compact}" data-action="compact"></button></div></div></section></div></div>`;}

function openDialog(title,body){const d=document.querySelector('#dialog');d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}`;if(!d.open)d.showModal();}
function download(name,value){const b=new Blob([value],{type:'application/json'}),url=URL.createObjectURL(b);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);toast('Download requested. Check the browser downloads.');}
function confirmReplace(kind){openDialog(kind==='clear'?'Clear this session?':'Replace the current dataset?',`<p>This removes current events, alerts, reports, notes, bookmarks, and case decisions from this tab. Downloaded files are unaffected.</p><div class="actions">${btn('Cancel','close')}${btn(kind==='clear'?'Clear session':'Load scenario',`replace:${kind}`,'',true)}</div>`);}
async function action(name){const a=alerts.find(x=>x.id===selected);if(titles[name])return navigate(name);
 if(name==='quick-actions'){saveProfileDraft();openDialog('Make your next move',`<p>Jump straight into your workspace.</p><div class="quick-grid">${[['next-case','target','Next investigation','Open the highest-priority unresolved signal'],['saved','bookmark','Your watchlist','Pick up a saved investigation'],['lab','flask','Scenario lab','Explore a reproducible security scenario'],['evaluations','checklist','Rule evaluations','Check your detection baseline'],['profile','palette','Personalize workspace','Choose your palette, profile, and theme'],['privacy','lock','Privacy controls','See how this lab handles data']].map(([action,ico,title,desc])=>`<button class="quick-card" data-action="${action}"><span>${icon(ico)}</span><strong>${title}</strong><small>${desc}</small>${icon('arrow')}</button>`).join('')}</div>`);return;}
 if(name==='next-case'){const next=alerts.find(x=>x.status!=='Resolved');if(next){selected=next.id;navigate('detail');}else{navigate('alerts');toast('No unresolved alerts. Explore a scenario to start a new investigation.');}return;}
 if(name==='bookmark'&&a){const key=bookmarkKey(a);if(bookmarks.has(key))bookmarks.delete(key);else bookmarks.add(key);log(`${a.id} ${isSaved(a)?'saved to':'removed from'} your watchlist.`);render();toast(isSaved(a)?'Investigation saved for this session.':'Bookmark removed.');return;}
 if(name==='save-profile'){
 const name=document.querySelector('#profile-name').value.trim();const role=document.querySelector('#profile-role').value;const bio=document.querySelector('#profile-bio').value.trim();
 if(!name||Array.from(name).length>40){document.querySelector('#profile-error').textContent='Enter a display name between 1 and 40 characters.';document.querySelector('#profile-name').focus();return;}
 if(!profileRoleOptions.includes(role))return;
 profile={...profile,name,role,bio:bio.slice(0,180)};log('Updated local profile.');render();toast('Profile saved for this session.');return;
 }
 if(name==='activity-panel'){openDialog('Workspace activity',`<p>Actions from your current session. No external notifications.</p><div class="activity-list">${audit.slice(0,8).map(a=>`<div class="event"><div class="event-icon">${icon('activity')}</div><div>${esc(a.text)}<small>${time(a.at)} UTC</small></div></div>`).join('')}</div>`);return;}
 if(name==='compact'){saveProfileDraft();profile.compact=!profile.compact;render();return;}
 if(name==='menu'){document.querySelector('.sidebar').classList.toggle('open');return;}
 if(name==='close'){document.querySelector('#dialog').close();return;}
 if(name==='mask'){mask=!mask;render();return;}
 if(name==='prev'||name==='next'){logPage+=name==='next'?1:-1;render();return;}
 if(name==='audit'){activeTab='audit';navigate('privacy');return;}
 if(name==='reset'||name==='clear'){confirmReplace(name==='reset'?'all':'clear');return;}
 if(name.startsWith('scenario:')){confirmReplace(name.split(':')[1]);return;}
 if(name.startsWith('replace:')){const kind=name.split(':')[1];bookmarks.clear();events=kind==='clear'?[]:fixtures(kind);if(kind==='clear')profile={name:'Lab Analyst',role:'Security researcher',bio:'Following the evidence. Building a safer digital world.',color:'raspberry',theme:'daylight',accent:'raspberry',compact:false};alerts=detect(events,enabled);selected=null;evaluations=null;audit.length=0;log(kind==='clear'?'Session data cleared.':`Loaded synthetic ${kind} scenario.`);document.querySelector('#dialog').close();navigate(kind==='clear'?'privacy':'alerts');toast(kind==='clear'?'Session cleared. Reload to restore demo.':'Scenario loaded. Review the detected alerts.');return;}
 if(name==='investigate'&&a){a.report=investigate(a,events);a.status='Investigating';log(`Generated rules-based brief for ${a.id}.`);render();return;}
 if(name==='note'&&a){const text=document.querySelector('#note').value.trim();if(!text)return toast('Write a lab observation first.');a.notes.unshift({at:new Date().toISOString(),text:text.slice(0,1000)});log(`Added a session-only note to ${a.id}.`);render();toast('Note added. It will not be exported.');return;}
 if(name==='run-evals'){evaluations=evaluate();log(`Ran ${evaluations.length} synthetic rule checks.`);render();toast(`${evaluations.filter(r=>r.pass).length}/${evaluations.length} checks passed.`);return;}
 if(name==='export-evals'&&evaluations){download('traceguard-evaluation.json',JSON.stringify({scope:'synthetic functional tests',results:evaluations},null,2));return;}
 if(name==='export-report'&&a?.report){download(`${a.id}-redacted-report.json`,JSON.stringify(exportBrief(a),null,2));log(`Exported redacted report for ${a.id}; notes excluded.`);return;}
 if(name==='export-alerts'){download('traceguard-alert-summary.json',JSON.stringify({labOnly:true,alerts:alerts.map(({id,ruleId,severity,status,time})=>({id,ruleId,severity,status,time}))},null,2));log('Exported minimized alert summary.');return;}
 if(name==='sample'){download('traceguard-synthetic-sample.json',JSON.stringify(fixtures('takeover'),null,2));return;}
 if(name==='import'){openDialog('Import synthetic lab events',`<p>Only the TraceGuard lab schema is accepted. Use generated data, <strong>demo-</strong> account names, and documentation IP addresses. Files stay in this tab’s memory.</p><div class="actions">${btn('Download sample','sample','download')}</div><label for="event-file">Synthetic JSON file · maximum 1 MB / 2,000 events</label><input class="file-drop" type="file" id="event-file" accept=".json,application/json"><p class="subtle">Importing replaces current events and case work.</p><div id="import-error" class="error" role="alert"></div><div class="actions">${btn('Cancel','close')}${btn('Validate & import','import-confirm','upload',true)}</div>`);return;}
 if(name==='import-confirm'){const file=document.querySelector('#event-file').files[0];try{if(!file)throw new Error('Choose a synthetic JSON file.');if(file.size>1048576)throw new Error('File exceeds the 1 MB limit.');const imported=validateEvents(JSON.parse(await file.text()));events=imported;bookmarks.clear();alerts=detect(events,enabled);selected=null;log(`Imported ${events.length} validated lab events; previous case work cleared.`);document.querySelector('#dialog').close();navigate('alerts');toast(`${events.length} lab events imported locally.`);}catch(e){document.querySelector('#import-error').textContent=e instanceof SyntaxError?'Invalid JSON. Download the sample to check the format.':e.message;}return;}
 if(name==='search'){openDialog('Find an alert',`<label for="global-search">Search by alert title, ID, or lab account</label><input id="global-search" class="field search-field" placeholder="Try demo-alex or TG-1001" autocomplete="off"><div id="search-results"></div>`);document.querySelector('#global-search').focus();searchResults('');return;}
}
function searchResults(value){document.querySelector('#search-results').innerHTML=alerts.filter(a=>`${a.id} ${a.title} ${a.account}`.toLowerCase().includes(value.toLowerCase())).slice(0,6).map(a=>`<button class="result-item" data-open="${a.id}">${esc(a.title)}<small>${a.id} · ${a.account}</small></button>`).join('')||'<p class="subtle">No matching alerts.</p>';}
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.theme&&['midnight','daylight'].includes(t.dataset.theme)){const inSidebar=!!t.closest('.sidebar');const wasOpen=!!document.querySelector('.sidebar.open');saveProfileDraft();profile.theme=t.dataset.theme;render();if(wasOpen)document.querySelector('.sidebar').classList.add('open');document.querySelector(`${inSidebar?'.theme-switch':'.appearance-options'} [data-theme="${profile.theme}"]`)?.focus({preventScroll:true});return;}if(t.dataset.accent&&['raspberry','graphite','jade'].includes(t.dataset.accent)){saveProfileDraft();profile.accent=t.dataset.accent;render();return;}if(t.dataset.avatar&&['raspberry','graphite','jade','petal'].includes(t.dataset.avatar)){saveProfileDraft();profile.color=t.dataset.avatar;render();return;}if(t.dataset.focus&&['open','critical','saved'].includes(t.dataset.focus)){dashboardFocus=t.dataset.focus;render();document.querySelector(`[data-focus="${dashboardFocus}"]`)?.focus({preventScroll:true});return;}if(t.dataset.nav){navigate(t.dataset.nav);return;}if(t.dataset.open){selected=t.dataset.open;document.querySelector('#dialog').close();navigate('detail');return;}if(t.dataset.action){void action(t.dataset.action);return;}if(t.dataset.rule){const id=t.dataset.rule;if(enabled.has(id))enabled.delete(id);else enabled.add(id);rerun();log(`${id} ${enabled.has(id)?'enabled':'disabled'}; dataset reprocessed.`);render();return;}if(t.dataset.tab){activeTab=t.dataset.tab;render();}});
document.addEventListener('change',e=>{if(e.target.id==='severity'){severity=e.target.value;render();}if(e.target.id==='status-filter'){statusFilter=e.target.value;render();}if(e.target.id==='log-type'){logType=e.target.value;logPage=0;render();}if(e.target.id==='case-status'){const a=alerts.find(x=>x.id===selected);a.status=e.target.value;log(`${a.id} marked ${a.status.toLowerCase()}.`);render();toast('Case status updated for this session.');}});
document.addEventListener('input',e=>{if(e.target.id==='global-search'){searchResults(e.target.value);return;}if(['alert-search','log-search'].includes(e.target.id)){const id=e.target.id,position=e.target.selectionStart;filter=e.target.value;logPage=0;render();const input=document.getElementById(id);input.focus();input.setSelectionRange(position,position);}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();action('search');}if(e.key==='Escape')document.querySelector('.sidebar')?.classList.remove('open');});
function evidenceHealth(){const open=alerts.filter(a=>a.status!=='Resolved').length;const completeness=Math.min(100,Math.round((enabled.size/RULES.length*.45+Math.min(events.length/160,1)*.35+(open?0.2:0))*100));return `<section class="evidence-health"><div class="health-intro"><span class="eyebrow">${icon('radar')} INVESTIGATION POSTURE</span><h2>Evidence health <strong>${completeness}%</strong></h2><p>See how ready this synthetic workspace is for a focused review.</p>${btn('View detection coverage','rules','layers')}</div><div class="health-grid"><article><span>${icon('database')}</span><div><strong>${events.length}</strong><small>Validated lab events</small></div><i>${icon('check')}</i></article><article><span>${icon('layers')}</span><div><strong>${enabled.size}/${RULES.length}</strong><small>Detection rules active</small></div><i>${icon('check')}</i></article><article><span>${icon('target')}</span><div><strong>${open}</strong><small>Signals need review</small></div><i>${icon(open?'arrow':'check')}</i></article></div></section>`;}
function coverageMap(){return `<section class="coverage-map"><div><span class="eyebrow">${icon('layers')} COVERAGE MAP</span><h2>Rules with a clear purpose.</h2><p>Every enabled rule has a visible technique mapping and a testable outcome.</p></div><div class="coverage-items">${RULES.map(r=>`<article><span>${icon(r.id==='TG-003'?'user':'shield')}</span><div><strong>${esc(r.id)}</strong><small>${esc(r.mitre)}</small></div><b>${enabled.has(r.id)?'Active':'Paused'}</b></article>`).join('')}</div></section>`;}
function roleInfo(){return {'Owner':{icon:'shield',scope:'Approves access, sets the security direction, and reviews sensitive decisions.'},'Lab assistant':{icon:'activity',scope:'Works in an owner-approved scope to review evidence and document decisions.'}}[workspaceRole]||{icon:'shield',scope:'Local policy preview only. Real roles are enforced by the organization server.'};}
function commandCenter(){const open=alerts.filter(a=>a.status!=='Resolved'),critical=open.filter(a=>a.severity==='critical'),next=critical[0]||open[0],role=roleInfo();return `<section class="command-banner command-center"><div class="command-copy"><span class="eyebrow">${icon('radar')} OPERATIONS CENTER · SYNTHETIC DEMO</span><h2><span>${critical.length} critical signal${critical.length===1?'':'s'}</span> need${critical.length===1?'s':''} review.</h2><p>${next?`Next priority: ${esc(next.title)} for ${esc(next.account)}.`:'No unresolved signals. Load a scenario to begin a review.'} Current owner role: ${esc(workspaceRole)}.</p><div class="hero-actions">${btn(next?'Open priority case':'Open scenario lab',next?'next-case':'lab',next?'target':'flask',true)}<span>${icon(role.icon)}${esc(role.scope)}</span></div></div><div class="command-stack"><article><span>${icon('bell')} Queue</span><strong>${open.length}</strong><small>open signals</small></article><article><span>${icon('layers')} Coverage</span><strong>${enabled.size}/${RULES.length}</strong><small>rules active</small></article><article><span>${icon('lock')} Data boundary</span><strong>Lab-only</strong><small>no customer systems</small></article></div></section>`;}
function ownerPulse(){const role=roleInfo();const roles=['Owner','Lab assistant'];return `<section class="owner-pulse"><div class="owner-copy"><span class="eyebrow">${icon('layers')} AUTHORIZED WORKFLOW · LOCAL PREVIEW</span><h2>Access starts with an owner-approved identity.</h2><p>The production model limits workspace access to an organization owner and an explicitly authorized lab assistant. This browser view only illustrates that policy; it does not grant access to a real system.</p><div class="role-choices" role="group" aria-label="Local policy preview role">${roles.map(name=>`<button data-workspace-role="${name}" aria-pressed="${workspaceRole===name}">${icon(roleInfoFor(name).icon)}${esc(name)}</button>`).join('')}</div><p class="local-note">${icon('lock')}Production access requires company SSO, passkey or authenticator-app MFA, server-side roles, and tenant isolation.</p><div class="actions">${btn('Open launch checklist','owner-center','checklist',true)}${btn('Download owner brief','download-owner-brief','download')}</div></div><div class="owner-board"><article><span>${icon(role.icon)}</span><div><small>Selected local view</small><strong>${esc(workspaceRole)}</strong><p>${esc(role.scope)}</p></div></article><article><span>${icon('file')}</span><div><small>Evidence handoff</small><strong>Redacted exports</strong><p>Notes and source addresses stay out of exported reports.</p></div></article><article><span>${icon('database')}</span><div><small>Data sources</small><strong>Integration-ready</strong><p>Connector contracts are scoped; live sources stay disconnected.</p></div></article><div class="connection-grid">${[['Okta','identity'],['Microsoft Entra ID','identity'],['GitHub','audit'],['AWS CloudTrail','cloud']].map(([name,type])=>`<div><span>${icon(type==='cloud'?'layers':'server')}</span><strong>${name}</strong><small>Prototype connector · disconnected</small></div>`).join('')}</div></div></section>`;}
function roleInfoFor(name){return {'Owner':{icon:'shield'},'Lab assistant':{icon:'activity'}}[name]||{icon:'shield'};}
function caseCommand(a){const impact=a.severity==='critical'?'Potential account takeover':a.severity==='high'?'Repeated authentication risk':'Privileged-access change review';const checklist=a.ruleId==='TG-003'?['Verify the approved role-change record.','Confirm the account owner and change ticket.','Document the human decision.']:['Verify the event sequence and source context.','Confirm the account owner or approved activity.','Document the evidence-backed decision.'];return `<section class="case-command"><div class="case-command-head"><div><span class="eyebrow">${icon('target')} CASE WORKFLOW · LOCAL DEMO</span><h2>Make the next decision clear.</h2></div>${btn('Manage role view','owner-center','user')}</div><div class="case-facts"><article><span>${icon('user')}</span><small>Review owner</small><strong>${esc(workspaceRole)}</strong></article><article><span>${icon('file')}</span><small>Evidence basis</small><strong>${a.evidence.length} linked events</strong></article><article><span>${icon('server')}</span><small>Source</small><strong>Identity lab fixture</strong></article><article><span>${icon('target')}</span><small>Potential impact</small><strong>${impact}</strong></article></div><div class="case-checklist"><span>${icon('checklist')} Recommended review steps</span><ol>${checklist.map(step=>`<li>${icon('check')}<span>${step}</span></li>`).join('')}</ol></div></section>`;}
function ownerReadinessDialog(){const items=[['Implemented now','Synthetic-only event validation, evidence-linked alerts, redacted exports, reproducible rules, and local session controls.','check'],['Access policy preview','Organization owner approval, authorized lab-assistant scope, company SSO, and passkey or authenticator-app MFA.','shield'],['Required before customer data','Server-side authentication and authorization, tenant isolation, durable audit records, encryption, monitoring, and reviewed data agreements.','lock']];openDialog('Company launch checklist',`<p class="dialog-intro">This is the operating model a company owner should expect. The current build is an enterprise-style prototype, not a live customer-data platform.</p><div class="readiness-list">${items.map(([title,description,ico])=>`<article><span>${icon(ico)}</span><div><strong>${title}</strong><p>${description}</p></div></article>`).join('')}</div><div class="dialog-role"><span>Preview the authorized workflow as:</span><div class="role-choices" role="group" aria-label="Local policy preview role">${['Owner','Lab assistant'].map(name=>`<button data-workspace-role="${name}" aria-pressed="${workspaceRole===name}">${icon(roleInfoFor(name).icon)}${esc(name)}</button>`).join('')}</div></div><div class="actions">${btn('Download owner brief','download-owner-brief','download')}${btn('Start guided demo','start-owner-demo','play',true)}</div>`);}
function ownerBrief(){return {product:'TraceGuard enterprise-style prototype',scope:'Synthetic identity-event investigation workspace',current_role:workspaceRole,implemented:['Synthetic-only validation','Transparent detections','Evidence-linked case review','Redacted exports','Reproducible evaluation checks'],demonstrated:['Local workflow roles','Disconnected integration contracts','Company launch checklist'],before_customer_data:['Authentication and server-side authorization','Tenant isolation','Durable encrypted storage and audit trail','Monitoring, rate limits, backups, and incident response','Reviewed data retention and AI-provider policy']};}
const initialApplyStyles=applyStyles;
applyStyles=()=>{initialApplyStyles();const renamed={raspberry:'amethyst',petal:'orchid'};document.querySelectorAll('[data-accent],[data-avatar]').forEach(control=>{const key=control.dataset.accent?'accent':'avatar';const original=control.dataset[key],next=renamed[original]||original;if(next!==original){control.dataset[key]=next;control.classList.remove(original);control.classList.add(next);}if(key==='accent'){control.setAttribute('aria-label',`${next} accent`);control.setAttribute('aria-pressed',String(profile.accent===next));}else{control.setAttribute('aria-label',`${next} avatar`);control.setAttribute('aria-pressed',String(profile.color===next));}});const palette=document.querySelector('[aria-label="Accent color"]');if(palette&&!palette.querySelector('[data-accent="orchid"]')){const orchid=document.createElement('button');orchid.type='button';orchid.className='palette-choice orchid';orchid.dataset.accent='orchid';orchid.setAttribute('aria-label','orchid accent');orchid.setAttribute('aria-pressed',String(profile.accent==='orchid'));orchid.innerHTML='<span class="palette-swatch"></span>Orchid';palette.append(orchid);}};
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.accent&&['amethyst','orchid','graphite','jade'].includes(t.dataset.accent)){e.stopImmediatePropagation();saveProfileDraft();profile.accent=t.dataset.accent;render();return;}if(t.dataset.avatar&&['amethyst','orchid','graphite','jade'].includes(t.dataset.avatar)){e.stopImmediatePropagation();saveProfileDraft();profile.color=t.dataset.avatar;render();}},true);
const initialAction=action;
action=async name=>{await initialAction(name);if(name==='replace:clear'){profile={name:'Lab Analyst',role:'Security researcher',bio:'Following the evidence. Building a safer digital world.',color:'amethyst',theme:'daylight',accent:'amethyst',compact:false};render();}};
const actionWithOwnerControls=action;
action=async name=>{if(name==='owner-center'){ownerReadinessDialog();return;}if(name==='download-owner-brief'){download('traceguard-owner-brief.json',JSON.stringify(ownerBrief(),null,2));log('Downloaded an owner-ready prototype brief.');return;}if(name==='start-owner-demo'){document.querySelector('#dialog').close();navigate('lab');toast('Start with a reproducible scenario, then investigate the evidence.');return;}return actionWithOwnerControls(name);};
document.addEventListener('click',e=>{const control=e.target.closest('button[data-workspace-role]');if(!control)return;e.stopImmediatePropagation();const next=control.dataset.workspaceRole;if(!['Owner','Lab assistant'].includes(next))return;const dialogWasOpen=document.querySelector('#dialog').open;workspaceRole=next;log(`Local policy preview role changed to ${workspaceRole}.`);render();if(dialogWasOpen)ownerReadinessDialog();toast(`Viewing the policy as ${workspaceRole}.`);},true);
const renamePaletteLabels=applyStyles;
applyStyles=()=>{renamePaletteLabels();document.querySelectorAll('.palette-choice[data-accent="amethyst"]').forEach(button=>{if(button.lastChild)button.lastChild.textContent='Amethyst';});};
banner=commandCenter;
const initialOverview=overview;
overview=()=>initialOverview().replace('<div class="bottom-row">',evidenceHealth()+ownerPulse()+'<div class="bottom-row">');
const initialRulesView=rulesView;
rulesView=()=>initialRulesView().replace('<div class="notice">',coverageMap()+'<div class="notice">');
const initialDetailView=detailView;
detailView=()=>{const alert=alerts.find(item=>item.id===selected);return alert?initialDetailView().replace('<div class="split row-gap">',caseCommand(alert)+'<div class="split row-gap">'):initialDetailView();};
// The executive layer is intentionally local and synthetic. It gives a buyer
// concrete value, governance, and pilot answers without implying live access.
paths.calendar='M5 4h14v16H5z M8 2v4 M16 2v4 M5 9h14 M9 13h2 M13 13h2 M9 17h2';
const executivePlanner={reviews:80,minutes:12,cost:65};
function boundedNumber(value,min,max,fallback){const number=Number(value);return Number.isFinite(number)?Math.min(max,Math.max(min,number)):fallback;}
function executiveMath(){const reviews=boundedNumber(executivePlanner.reviews,1,50000,80),minutes=boundedNumber(executivePlanner.minutes,1,240,12),cost=boundedNumber(executivePlanner.cost,1,1000,65),hours=reviews*minutes/60,savings=hours*cost;return {reviews,minutes,cost,hours,savings,annual:savings*12};}
function readableNumber(value,maximumFractionDigits=0){return new Intl.NumberFormat('en-US',{maximumFractionDigits}).format(value);}
function executiveScoreboard(){const open=alerts.filter(a=>a.status!=='Resolved'),critical=open.filter(a=>a.severity==='critical'),evidenceRate=alerts.length?Math.round(alerts.filter(a=>a.evidence.length>0).length/alerts.length*100):100;return `<section class="executive-scoreboard" aria-label="Executive scorecard"><article><span>${icon('target')}</span><small>Critical review queue</small><strong>${critical.length}</strong><p>${critical.length?'Human review required':'No critical signals waiting'}</p></article><article><span>${icon('file')}</span><small>Evidence traceability</small><strong>${evidenceRate}%</strong><p>${alerts.length} synthetic alerts cite events</p></article><article><span>${icon('layers')}</span><small>Rule assurance</small><strong>${enabled.size}/${RULES.length}</strong><p>Transparent rules currently active</p></article><article><span>${icon('lock')}</span><small>External data egress</small><strong>0</strong><p>Browser lab has no live connection</p></article></section>`;}
function executiveView(){const value=executiveMath();return heading('Executive brief','A buyer-ready view of value, governance, and a safe path to a pilot.',btn('Download executive brief','download-executive-brief','download')+btn('Open launch checklist','owner-center','checklist',true))+`<section class="executive-hero"><div><span class="executive-eyebrow">${icon('radar')} LEADERSHIP VIEW · SYNTHETIC PROTOTYPE</span><h2>Turn identity signals into <span>faster, evidence-backed decisions.</span></h2><p>TraceGuard makes the operating model visible before a customer connects a single system: what is detected, who owns the decision, how evidence is handled, and how a pilot proves value.</p><div class="executive-actions">${btn('Plan a 30-day pilot','pilot-plan','calendar',true)}${btn('Review trust controls','privacy','lock')}</div><p class="executive-boundary">${icon('lock')} Planning values are illustrative. This browser workspace contains synthetic fixtures only and has no external network connection.</p></div><div class="executive-hero-side"><span>WHAT AN OWNER GETS</span><article>${icon('clock')}<div><strong>Faster review</strong><small>Model capacity before a pilot starts.</small></div></article><article>${icon('shield')}<div><strong>Visible trust</strong><small>Data boundary and launch controls are explicit.</small></div></article><article>${icon('checklist')}<div><strong>Accountable rollout</strong><small>Stop/go gates keep a pilot safe.</small></div></article></div></section>${executiveScoreboard()}<section class="value-planner"><div class="value-planner-copy"><span class="eyebrow">${icon('chart')} VALUE PLANNING MODEL</span><h2>Make the business case transparent.</h2><p>Use your own pilot assumptions. The result is a planning estimate, never a claim about measured customer savings.</p><div class="value-inputs"><label>Alert reviews / month<input class="field" data-value-field="reviews" type="number" min="1" max="50000" value="${value.reviews}" inputmode="numeric"></label><label>Minutes recovered / review<input class="field" data-value-field="minutes" type="number" min="1" max="240" value="${value.minutes}" inputmode="numeric"></label><label>Analyst cost / hour<input class="field" data-value-field="cost" type="number" min="1" max="1000" value="${value.cost}" inputmode="decimal"></label></div></div><div class="value-result" aria-live="polite"><span>Illustrative monthly capacity</span><article><small>Hours returned</small><strong data-value-output="hours">${readableNumber(value.hours,1)}</strong><p>hours available for higher-value work</p></article><article><small>Planning value</small><strong>$<span data-value-output="savings">${readableNumber(value.savings)}</span></strong><p>per month under these assumptions</p></article><article><small>Annualized planning view</small><strong>$<span data-value-output="annual">${readableNumber(value.annual)}</span></strong><p>not measured ROI or a contract promise</p></article></div></section><section class="pilot-plan"><div class="pilot-plan-head"><div><span class="eyebrow">${icon('compass')} SAFE 30-DAY PILOT</span><h2>Prove usefulness before production access.</h2><p>Every phase has an owner, a measurable outcome, and a stop/go gate.</p></div>${btn('Open full pilot plan','pilot-plan','checklist')}</div><div class="pilot-steps"><article><span>0</span><div><small>Before data</small><strong>Security review & agreement</strong><p>Define approved source fields, retention, escalation owner, and no-egress boundary.</p></div></article><article><span>1</span><div><small>Week 1</small><strong>Read-only test fixture</strong><p>Validate schemas and baselines with synthetic or approved test-tenant events.</p></div></article><article><span>2</span><div><small>Weeks 2–3</small><strong>Detection & workflow tuning</strong><p>Review three rules, cited evidence, and analyst decision quality.</p></div></article><article><span>3</span><div><small>Week 4</small><strong>Outcome review</strong><p>Measure agreed targets and make a documented stop/go decision.</p></div></article></div><div class="pilot-success"><strong>${icon('target')} Pilot success targets</strong><span>90% evidence-linked cases</span><span>Agreed critical-case response target</span><span>0 unapproved data egress</span></div></section><section class="governance-grid"><article class="governance-card status-implemented"><span>${icon('check')}</span><small>IMPLEMENTED NOW</small><h3>Synthetic data boundary</h3><p>Demo accounts and documentation-only addresses are validated before processing.</p><strong>Safe for portfolio demonstration</strong></article><article class="governance-card status-demo"><span>${icon('layers')}</span><small>DEMONSTRATED HERE</small><h3>Decision accountability</h3><p>Role views, evidence-linked cases, review steps, and session activity make ownership visible.</p><strong>Local workflow simulation</strong></article><article class="governance-card status-required"><span>${icon('lock')}</span><small>REQUIRED BEFORE LIVE DATA</small><h3>Enterprise controls</h3><p>Authentication, tenancy, durable audit records, encryption, monitoring, backups, and incident response.</p><strong>Planned launch gate</strong></article></section><section class="buyer-questions"><div><span class="eyebrow">${icon('help')} OWNER QUESTIONS, ANSWERED</span><h2>The questions a serious buyer should ask.</h2></div><div class="questions-list"><details open><summary>What measurable outcome will I get?${icon('chevron')}</summary><p>A controlled pilot measures evidence-linked case quality, critical-case response targets, and analyst capacity using agreed baselines.</p></details><details><summary>How can we try this safely?${icon('chevron')}</summary><p>Start with synthetic or approved test-tenant events, read-only scopes, an explicit data agreement, and stop/go gates before any live rollout.</p></details><details><summary>What data leaves our environment?${icon('chevron')}</summary><p>In this demo: none. The browser lab has no API or AI connection. A production design would require a documented data-flow and vendor review.</p></details><details><summary>Who owns a critical case?${icon('chevron')}</summary><p>The workflow names a review role, shows cited evidence, and requires a human decision. It never changes an account automatically.</p></details></div></section><section class="ai-governance"><div class="ai-copy"><span class="eyebrow">${icon('sparkles')} RESPONSIBLE ASSISTANCE</span><h2>Useful AI starts with guardrails.</h2><p>TraceGuard does not connect to a language model today. Its deterministic evidence assistant demonstrates the standard a future AI feature must meet: cited facts, human approval, and no autonomous remediation.</p></div><div class="ai-guardrails"><article>${icon('file')}<div><strong>Evidence cited</strong><small>Every explanation points back to event IDs.</small></div></article><article>${icon('eye')}<div><strong>Human decides</strong><small>No assistant can close a case or change an account.</small></div></article><article>${icon('lock')}<div><strong>Data policy first</strong><small>No prompts, logs, or customer data leave this lab.</small></div></article></div></section>`;}
function ownerReview(){const strengths=[['shield','Security product judgment','Detection, containment, and human review are designed around real security decisions.'],['file','Evidence-led workflow','Signals point to cited facts, review steps, owners, and recorded decisions.'],['lock','Data-boundary maturity','Synthetic fixtures, redacted exports, and explicit no-egress limits are visible.'],['chart','Owner & business thinking','A pilot plan, success targets, and a transparent value model make the business case reviewable.'],['check','Visible quality & testing','The interface, responsive workflows, and repeatable checks make the work easy to assess.']];return `<section class="owner-review" aria-labelledby="owner-review-title"><div class="owner-review-header"><div class="owner-review-copy"><span class="eyebrow">${icon('shield')} OWNER REVIEW · PORTFOLIO PROTOTYPE</span><h2 id="owner-review-title">Interview-ready portfolio</h2><p>This is a concise portfolio-readiness assessment of the synthetic TraceGuard prototype: it demonstrates security judgment, product thinking, and execution quality without claiming a production deployment.</p></div><div class="owner-score" aria-label="Portfolio readiness score: 10 out of 10"><small>PORTFOLIO READINESS</small><strong>10 <span>/ 10</span></strong><b>${icon('check')}Interview-ready portfolio</b></div></div><div class="owner-strengths" aria-label="Why this portfolio stands out">${strengths.map(([ico,title,description])=>`<article><span>${icon(ico)}</span><div><strong>${esc(title)}</strong><p>${esc(description)}</p></div></article>`).join('')}</div><aside class="owner-live-gate" aria-labelledby="live-data-gate-title"><div><span class="eyebrow">${icon('lock')} BEFORE LIVE CUSTOMER DATA</span><h3 id="live-data-gate-title">Build the production gate first.</h3><p>A strong prototype names what must be true before a company connects people, systems, or evidence.</p></div><ul><li>${icon('user')}Tenant authentication and server-enforced roles</li><li>${icon('server')}Reviewed identity-provider integration with least-privilege scopes</li><li>${icon('file')}Durable audit records, encryption, monitoring, and incident response</li></ul></aside><p class="owner-review-disclaimer">${icon('lock')}This is a portfolio-readiness assessment of a local synthetic prototype, not a third-party endorsement, certification, or production approval.</p></section>`;}
const executiveViewWithOwnerReview=executiveView;
executiveView=()=>executiveViewWithOwnerReview().replace('<section class="governance-grid">',ownerReview()+'<section class="governance-grid">');
function executiveBrief(){const value=executiveMath();return {product:'TraceGuard executive brief',scope:'Synthetic-only cybersecurity investigation prototype',generated_at:new Date().toISOString(),current_state:{synthetic_events:events.length,alerts:alerts.length,open_alerts:alerts.filter(a=>a.status!=='Resolved').length,active_rules:`${enabled.size}/${RULES.length}`,external_data_egress:0,ai_connected:false},illustrative_pilot_model:{alert_reviews_per_month:value.reviews,minutes_recovered_per_review:value.minutes,analyst_cost_per_hour:value.cost,estimated_hours_returned:value.hours,estimated_monthly_planning_value:value.savings,disclaimer:'Illustrative planning model only. This is not measured customer ROI or a contract promise.'},pilot_success_targets:['90% evidence-linked cases','Agreed critical-case response target','Zero unapproved data egress'],before_live_customer_data:['Authentication and server-enforced authorization','Tenant isolation and durable audit records','Encryption, monitoring, backups, and incident response','Reviewed data retention, integrations, and AI-provider policy']};}
function pilotPlanDialog(){openDialog('30-day safe pilot plan',`<p class="dialog-intro">A company should be able to test value without taking an uncontrolled data risk. This plan starts with a security review and keeps each phase reversible.</p><div class="readiness-list"><article><span>0</span><div><strong>Before data: agree the boundary</strong><p>Assign a customer owner and TraceGuard owner. Approve source fields, retention, escalation, and stop/go criteria.</p></div></article><article><span>1</span><div><strong>Week 1: test fixture and baseline</strong><p>Use synthetic or approved test-tenant identity events. Validate read-only scope and expected normal activity.</p></div></article><article><span>2</span><div><strong>Weeks 2–3: review evidence quality</strong><p>Tune the three detections, compare analyst decisions, and verify that cases cite supporting events.</p></div></article><article><span>3</span><div><strong>Week 4: outcome review</strong><p>Measure agreed success targets. Choose to stop, iterate, or design a production implementation.</p></div></article></div><div class="actions">${btn('Download executive brief','download-executive-brief','download',true)}${btn('Open trust controls','privacy','lock')}</div>`);}
function governanceRegistry(){const meta={"TG-001":['Identity detection owner','v1.2','Failure threshold verified'],"TG-002":['Identity detection owner','v1.2','Sequence logic verified'],"TG-003":['Access governance owner','v1.1','Change review verified']};return `<section class="rule-governance"><div><span class="eyebrow">${icon('checklist')} DETECTION GOVERNANCE</span><h2>Every detection is explainable, tested, owned, and reviewable.</h2><p>These are local prototype records that show the governance a buyer should expect before any detection reaches production.</p></div><div class="governance-registry">${RULES.map(rule=>{const [owner,version,test]=meta[rule.id];return `<article><span>${icon('shield')}</span><div><small>${esc(rule.id)} · ${esc(version)}</small><strong>${esc(rule.name)}</strong><p>${esc(rule.mitre)} · ${esc(rule.logic)}</p><footer><span>${icon('user')}${esc(owner)}</span><b>${icon('check')}${esc(test)}</b></footer></div></article>`;}).join('')}</div></section>`;}
function evidenceAssistant(alert){const evidence=events.filter(event=>alert.evidence.includes(event.id));const hypothesis={"TG-001":'This pattern may reflect password guessing, a mistyped password, or an outdated service credential.',"TG-002":'This sequence may reflect account takeover, but the event history alone does not prove compromise.',"TG-003":'This may be an approved change or an unauthorized privilege increase; verify the change record.'}[alert.ruleId];return `<section class="evidence-assistant"><div class="assistant-head"><div><span class="eyebrow">${icon('sparkles')} EVIDENCE ASSISTANT PREVIEW · DETERMINISTIC</span><h2>Separate observed facts from possibilities.</h2></div><span class="pill">${icon('lock')} No external AI model</span></div><div class="assistant-grid"><article><small>OBSERVED FACTS</small><ul>${evidence.slice(0,3).map(event=>`<li>${icon('check')}<span>${esc(eventLabel(event.type))}<b>${esc(event.id)}</b></span></li>`).join('')||`<li>${icon('file')}<span>No evidence linked.</span></li>`}</ul></article><article><small>POSSIBLE EXPLANATION</small><p>${esc(hypothesis)}</p><span class="assistant-note">A possibility is not a verdict.</span></article><article><small>NEXT HUMAN QUESTIONS</small><ul><li>${icon('help')}<span>Was this activity approved by the account or system owner?</span></li><li>${icon('help')}<span>What source-system evidence is still missing?</span></li></ul></article></div><div class="assistant-guardrail">${icon('shield')}<span>Read-only assistance: cites local evidence, cannot close a case, change an account, call external tools, or send data outside this browser lab.</span></div></section>`;}
Object.assign(titles,{executive:'Executive brief'});
const sidebarBeforeExecutive=sidebar;
sidebar=()=>{const leadership=`<div class="divider"></div><p class="navlabel">LEADERSHIP</p><nav class="nav" aria-label="Leadership tools"><button data-nav="executive" class="${view==='executive'?'active':''}" ${view==='executive'?'aria-current="page"':''}>${icon('chart')}Executive brief</button></nav>`;return sidebarBeforeExecutive().replace('<div class="sidebar-bottom">',leadership+'<div class="sidebar-bottom">');};
const renderBeforeExecutive=render;
render=()=>{if(view!=='executive')return renderBeforeExecutive();document.documentElement.dataset.theme=profile.theme;document.documentElement.dataset.accent=profile.accent;document.body.classList.toggle('compact',profile.compact);document.querySelector('#app').innerHTML=`<div class="layout">${sidebar()}<div class="page"><header class="topbar"><div class="breadcrumb"><button class="mobile-menu" aria-label="Toggle navigation" data-action="menu">${icon('menu')}</button><span>Workspace</span><span>/</span><strong>${titles[view]}</strong></div><div class="top-actions"><button class="quick-launch" data-action="quick-actions" aria-label="Open quick actions">${icon('bolt')}<span>Quick actions</span></button><button class="search-launch" data-action="search">${icon('search')}Search alerts <kbd>Ctrl K</kbd></button><span class="pill green"><span class="dot"></span>Synthetic lab</span><button class="icon-button" data-action="activity-panel" aria-label="Workspace activity">${icon('bell')}</button><button class="profile-trigger" data-nav="profile" aria-label="Open my profile">${avatar()}</button></div></header><main class="main" id="main" tabindex="-1">${executiveView()}<footer class="footer"><span>${icon('lock')}Session-only data · No model connection</span><span>TraceGuard / Security investigation lab <span class="mono">v0.1</span></span></footer></main></div></div>`;applyStyles();};
const actionBeforeExecutive=action;
action=async name=>{if(name==='download-executive-brief'){download('traceguard-executive-brief.json',JSON.stringify(executiveBrief(),null,2));log('Downloaded a synthetic executive brief.');return;}if(name==='pilot-plan'){pilotPlanDialog();return;}return actionBeforeExecutive(name);};
document.addEventListener('input',event=>{const key=event.target.dataset.valueField;if(!['reviews','minutes','cost'].includes(key))return;const limits={reviews:[1,50000,80],minutes:[1,240,12],cost:[1,1000,65]}[key];executivePlanner[key]=boundedNumber(event.target.value,...limits);const value=executiveMath();document.querySelectorAll('[data-value-output="hours"]').forEach(node=>node.textContent=readableNumber(value.hours,1));document.querySelectorAll('[data-value-output="savings"]').forEach(node=>node.textContent=readableNumber(value.savings));document.querySelectorAll('[data-value-output="annual"]').forEach(node=>node.textContent=readableNumber(value.annual));});
const rulesWithCoverage=rulesView;
rulesView=()=>rulesWithCoverage().replace('<div class="notice">',governanceRegistry()+'<div class="notice">');
const detailWithCaseCommand=detailView;
detailView=()=>{const alert=alerts.find(item=>item.id===selected);return alert?detailWithCaseCommand().replace('<div class="split row-gap">',evidenceAssistant(alert)+'<div class="split row-gap">'):detailWithCaseCommand();};
// Case commitment is deliberately a local workflow simulation. It makes the
// ownership and escalation story inspectable without sending a real message.
const caseWork=new Map();
const caseTargets={critical:{response:'15 min',decision:'4 hr'},high:{response:'1 hr',decision:'1 business day'},medium:{response:'4 hr',decision:'3 business days'},low:{response:'1 business day',decision:'5 business days'}};
const caseStages=[['Case assigned','The authorized lab assistant owns the first review.','activity'],['Response review','Owner review is planned at the response target.','shield'],['Decision review','Owner review is planned if the case remains unresolved.','target'],['Resolution review','A human decision and evidence summary are ready to record.','check']];
function caseRecord(alert){if(!caseWork.has(alert.id))caseWork.set(alert.id,{owner:'Lab assistant',stage:0,feedback:'Unrated',ledger:[{at:new Date().toISOString(),actor:'Local workflow',text:'Case entered the local review queue.',icon:'activity'}]});return caseWork.get(alert.id);}
function addCaseLedger(record,actor,text,iconName='check'){record.ledger.unshift({at:new Date().toISOString(),actor,text,icon:iconName});if(record.ledger.length>8)record.ledger.pop();}
function caseSla(alert){const record=caseRecord(alert),target=caseTargets[alert.severity]||caseTargets.low,[stageTitle,stageDescription,stageIcon]=caseStages[record.stage]||caseStages[0],status=alert.status==='Resolved'?'Resolved':alert.status==='Investigating'?'In review':'Open',health=alert.status==='Resolved'?'Decision recorded · demo':record.stage===0?'On track · demo':record.stage===1?'Response review due · demo':'Decision review due · demo',owners=['Lab assistant','Owner'];return `<section class="case-sla"><div class="sla-header"><div><span class="eyebrow">${icon('clock')} CASE COMMITMENT · LOCAL DEMO</span><h2>Make ownership and response commitments visible.</h2><p>Planning timeline only — no live paging, messaging, or notifications are sent.</p></div><span class="sla-status ${record.stage>0?'review':''}">${icon(stageIcon)}${esc(health)}</span></div><div class="sla-grid"><article class="sla-metric"><span>${icon('user')}</span><small>Case owner</small><strong>${esc(record.owner)}</strong><p>Local role choice</p></article><article class="sla-metric"><span>${icon('clock')}</span><small>Response target</small><strong>${esc(target.response)}</strong><p>Criticality-based demo target</p></article><article class="sla-metric"><span>${icon('checklist')}</span><small>Decision target</small><strong>${esc(target.decision)}</strong><p>Human disposition due</p></article><article class="sla-metric"><span>${icon('target')}</span><small>Current status</small><strong>${esc(status)}</strong><p>Fixture workflow state</p></article></div><div class="sla-progress" aria-label="Local case commitment progress">${caseStages.map(([title,description,ico],index)=>`<article class="${index<=record.stage?'active':''}"><span>${icon(index<=record.stage?'check':ico)}</span><div><small>${index===0?'0 min':index===1?target.response:index===2?target.decision:'Resolution'}</small><strong>${esc(title)}</strong><p>${esc(description)}</p></div></article>`).join('')}</div><div class="sla-controls"><div class="sla-owner"><span>${icon('user')} Assign local owner</span><div class="owner-choices" role="group" aria-label="Local case owner">${owners.map(owner=>`<button data-case-owner="${owner}" aria-pressed="${record.owner===owner}">${icon(owner==='Lab assistant'?'activity':'shield')}${esc(owner)}</button>`).join('')}</div></div><div class="sla-escalation"><div><span>${icon('layers')} Escalation path</span><strong>Lab assistant → Owner review</strong><p>Critical workflow: owner review is planned. Changes remain in this browser session.</p></div>${btn(record.stage<3?'Advance demo stage':'Demo stage complete','advance-case-stage',record.stage<3?'arrow':'check',true)}</div></div><p class="sla-note">${icon('lock')}This is a simulated workflow. Production use requires server-enforced ownership, durable audit records, notification integrations, and agreed SLAs.</p></section><section class="decision-ledger"><div class="ledger-head"><div><span class="eyebrow">${icon('file')} LOCAL DECISION LEDGER</span><h2>Keep the reason with the action.</h2></div><span class="pill">${record.ledger.length} session entries</span></div><div class="ledger-list">${record.ledger.slice(0,4).map(entry=>`<article class="ledger-entry"><span>${icon(entry.icon)}</span><div><strong>${esc(entry.actor)}</strong><p>${esc(entry.text)}</p></div><time>${time(entry.at)} UTC</time></article>`).join('')}</div></section><section class="case-feedback"><div><span class="eyebrow">${icon('sliders')} DETECTION FEEDBACK · LOCAL DEMO</span><h2>Capture whether this signal helped.</h2><p>Feedback is kept only in this tab. A production feedback loop would require governed rule review and durable audit records.</p></div><div class="feedback-choices" role="group" aria-label="Local detection feedback">${[['Useful signal','check'],['Needs tuning','sliders'],['False positive','help']].map(([label,ico])=>`<button data-case-feedback="${label}" aria-pressed="${record.feedback===label}">${icon(ico)}${label}</button>`).join('')}<small>${record.feedback==='Unrated'?'No feedback recorded yet.':`Current local feedback: ${record.feedback}.`}</small></div></section>`;}
const actionBeforeCaseCommitment=action;
action=async name=>{if(name==='advance-case-stage'){const alert=alerts.find(item=>item.id===selected);if(!alert)return;const record=caseRecord(alert);if(record.stage>=caseStages.length-1){toast('The final local workflow stage is already shown. Record a human disposition when ready.');return;}record.stage+=1;if(record.stage>=1)record.owner='Owner';const [title,description,ico]=caseStages[record.stage];addCaseLedger(record,'Local workflow',`${title}: ${description}`,ico);log(`${alert.id} advanced to ${title.toLowerCase()} in the local SLA demo.`);render();toast(`${title} shown in the local workflow.`);return;}if(name.startsWith('replace:'))caseWork.clear();return actionBeforeCaseCommitment(name);};
document.addEventListener('click',event=>{const button=event.target.closest('button[data-case-owner],button[data-case-feedback]');if(!button||!selected)return;const alert=alerts.find(item=>item.id===selected);if(!alert)return;const record=caseRecord(alert);if(button.dataset.caseOwner){record.owner=button.dataset.caseOwner;addCaseLedger(record,'Local workflow',`Owner set to ${record.owner}.`,'user');log(`${alert.id} local owner set to ${record.owner}.`);render();toast(`Local case owner: ${record.owner}.`);return;}if(button.dataset.caseFeedback){record.feedback=button.dataset.caseFeedback;addCaseLedger(record,'Lab assistant',`Feedback recorded: ${record.feedback}.`,'sliders');log(`${alert.id} received local feedback: ${record.feedback}.`);render();toast(`Local feedback recorded: ${record.feedback}.`);}},true);
document.addEventListener('change',event=>{if(event.target.id!=='case-status'||!selected)return;const alert=alerts.find(item=>item.id===selected);if(!alert)return;const record=caseRecord(alert);if(event.target.value==='Resolved')record.stage=caseStages.length-1;addCaseLedger(record,'Lab assistant',`Case status set to ${event.target.value}.`,'check');},true);
const detailWithEvidenceAssistant=detailView;
detailView=()=>{const alert=alerts.find(item=>item.id===selected);return alert?detailWithEvidenceAssistant().replace('<section class="evidence-assistant">',caseSla(alert)+'<section class="evidence-assistant">'):detailWithEvidenceAssistant();};
// This is intentionally only a browser-session demonstration of a containment
// decision. It never holds a credential, session token, device identifier, or
// customer connection, so it cannot change a real account or endpoint.
const containmentWork=new Map();
function containmentRecord(alert){if(!containmentWork.has(alert.id))containmentWork.set(alert.id,{contained:false,at:null});return containmentWork.get(alert.id);}
function accountContainment(alert){const record=containmentRecord(alert);const state=record.contained?`<span class="containment-state is-contained">${icon('check')}Contained-response demo recorded</span>`:`<span class="containment-state">${icon('shield')}Awaiting a verified decision</span>`;const actionText=record.contained?'Contained response simulated':'Simulate contained response';return `<section class="account-containment ${record.contained?'is-contained':''}"><div class="containment-intro"><div><span class="eyebrow">${icon('shield')} ACCOUNT CONTAINMENT · LOCAL DEMO</span><h2>Contain a suspicious successful login without crossing a tenant boundary.</h2><p>A signal is reviewed first. After a human or verified policy decision, a connected identity provider may temporarily revoke the suspicious session, then require a password reset and MFA re-verification.</p></div>${state}<div class="containment-action"><div><strong>${icon('clock')} Correct response sequence</strong><ol><li>Verify the signal and tenant policy.</li><li>Temporarily contain the suspicious session through the identity provider.</li><li>Require password reset and MFA re-verification.</li><li>Write a durable, reviewable audit record.</li></ol></div>${btn(actionText,'simulate-contained-response',record.contained?'check':'shield',true,record.contained?'disabled':'')}</div><p class="containment-disclaimer">${icon('lock')}Local simulation only: no password is changed, no session is revoked, no user is logged out, and no customer system, lab device, or USB is touched.</p></div><div class="tenant-boundary"><div class="boundary-head"><div><span class="eyebrow">${icon('layers')} MULTI-TENANT SAFEGUARDS</span><h3>One company’s people and evidence stay separate from another’s.</h3></div><span class="pill">Production requirements</span></div><div class="boundary-grid"><article><span>${icon('server')}</span><div><strong>Server-side tenant boundary</strong><p>Resolve the tenant from trusted server authentication, then scope every query and record to it.</p></div></article><article><span>${icon('shield')}</span><div><strong>Per-tenant role checks</strong><p>Enforce least-privilege roles on every server request, never only in the browser.</p></div></article><article><span>${icon('lock')}</span><div><strong>Isolated connector credentials</strong><p>Store each tenant’s connector secrets separately with minimal, audited scopes.</p></div></article><article><span>${icon('file')}</span><div><strong>Redacted exports</strong><p>Apply tenant-specific export policy and remove sensitive fields before delivery.</p></div></article></div><div class="device-boundary">${icon('flask')}<div><strong>Lab and USB boundary</strong><p>Endpoint or MDM policy must control removable media, operating-system access, and lab devices. A browser app cannot enforce those protections.</p></div></div></div></section>`;}
const actionBeforeContainment=action;
action=async name=>{if(name==='simulate-contained-response'){const alert=alerts.find(item=>item.id===selected);if(!alert)return;const record=containmentRecord(alert);if(record.contained){toast('The contained response is already shown in this local demo.');return;}record.contained=true;record.at=new Date().toISOString();const localCase=caseRecord(alert);addCaseLedger(localCase,'Local containment demo','Simulated a contained response. No password, session, user, device, or customer account was changed.','shield');log(`${alert.id} recorded a simulated contained response in this browser session.`);render();toast('Contained response simulated locally; no real account action was taken.');return;}if(name.startsWith('replace:'))containmentWork.clear();return actionBeforeContainment(name);};
const detailWithContainment=detailView;
detailView=()=>{const alert=alerts.find(item=>item.id===selected);return alert?detailWithContainment().replace('<section class="evidence-assistant">',accountContainment(alert)+'<section class="evidence-assistant">'):detailWithContainment();};
// The entry screen deliberately resembles a sign-in experience without ever
// authenticating a person. It has no credential fields, network calls, or
// stored tokens; it simply labels the local role used in this browser demo.
const demoRoles={
 'Owner':{icon:'shield',eyebrow:'Organization owner',description:'Approves access, sets the security direction, and reviews sensitive decisions.'},
 'Lab assistant':{icon:'activity',eyebrow:'Authorized assistant',description:'Reviews evidence and documents decisions within an owner-approved scope.'}
};
let demoEntered=false;
let demoRoleChoice=demoRoles[workspaceRole]?workspaceRole:'Owner';
function demoSignIn(){const role=demoRoles[demoRoleChoice]||demoRoles['Owner'];return `<div class="demo-signin-shell"><main class="demo-signin-main" id="main" tabindex="-1"><section class="demo-signin-story" aria-labelledby="demo-signin-title"><div class="demo-brand">${icon('shield')}<strong>TraceGuard</strong><span>LAB</span></div><div class="demo-story-copy"><span class="demo-kicker">${icon('sparkles')} IDENTITY SECURITY PORTFOLIO LAB</span><h1 id="demo-signin-title">A safer way to explore <em>security decisions.</em></h1><p>Step into a polished, synthetic-only investigation workspace built to show how evidence, ownership, and careful response work together.</p></div><div class="demo-signal-map" aria-hidden="true"><span class="demo-orbit demo-orbit-one"></span><span class="demo-orbit demo-orbit-two"></span><span class="demo-shield">${icon('shield')}</span><span class="demo-node demo-node-one">${icon('activity')}</span><span class="demo-node demo-node-two">${icon('check')}</span><span class="demo-node demo-node-three">${icon('lock')}</span></div><div class="demo-story-status" aria-label="Demo safety boundaries"><article><span>${icon('flask')}</span><div><strong>Synthetic-only</strong><small>Generated lab events, never customer records.</small></div></article><article><span>${icon('lock')}</span><div><strong>Private by design</strong><small>No credentials, tokens, or passwords are collected.</small></div></article><article><span>${icon('sparkles')}</span><div><strong>Model-free</strong><small>No external AI service or telemetry connection.</small></div></article></div><p class="demo-production-note">${icon('server')} A production deployment would use company SSO, MFA, and server-enforced tenant roles.</p></section><section class="demo-signin-panel" aria-labelledby="demo-entry-title"><div class="demo-panel-top"><span class="demo-panel-mark">${icon('lock')}</span><span class="demo-panel-status"><i></i>LOCAL DEMO ACCESS</span></div><div><h2 id="demo-entry-title">Enter the synthetic workspace</h2><p>Choose the point of view you want to use for this browser-only demonstration.</p></div><div class="demo-identity" role="note" aria-label="Synthetic lab identity"><span>${icon('user')}</span><div><small>LAB IDENTITY</small><strong>TraceGuard / Portfolio environment</strong><p>Not an account, tenant, or editable credential.</p></div><b>${icon('check')}Verified fixture</b></div><div class="demo-role-picker" role="group" aria-label="Choose a local demo role"><span class="demo-picker-label">LOCAL VIEW</span>${Object.entries(demoRoles).map(([name,info])=>`<button type="button" data-demo-role="${name}" aria-pressed="${demoRoleChoice===name}"><span>${icon(info.icon)}</span><div><small>${esc(info.eyebrow)}</small><strong>${esc(name)}</strong><p>${esc(info.description)}</p></div>${demoRoleChoice===name?`<i>${icon('check')}</i>`:''}</button>`).join('')}</div><div class="demo-entry-summary" aria-live="polite"><span>${icon(role.icon)}</span><div><small>SELECTED LOCAL VIEW</small><strong>${esc(demoRoleChoice)}</strong><p>${esc(role.description)}</p></div></div>${btn('Enter synthetic workspace','enter-synthetic-workspace','arrow',true)}<p class="demo-no-credential">${icon('lock')} No password, account, SSO request, or external connection is involved. This is not real authentication.</p><div class="demo-panel-footer"><span>${icon('eye')} No customer data</span><span>${icon('database')} Session-only state</span></div></section></main></div>`;}
function renderDemoSignIn(){document.documentElement.dataset.theme=profile.theme;document.documentElement.dataset.accent=profile.accent;document.body.classList.toggle('compact',false);document.body.classList.add('demo-signin');document.querySelector('#app').innerHTML=demoSignIn();}
const sidebarBeforeDemoSignIn=sidebar;
sidebar=()=>sidebarBeforeDemoSignIn().replace('<span class="sidebar-session">',`<button class="demo-signout" data-action="sign-out-demo" aria-label="Sign out of local demo">${icon('arrow')}Sign out of demo</button><span class="sidebar-session">`);
const renderBeforeDemoSignIn=render;
render=()=>{if(!demoEntered)return renderDemoSignIn();document.body.classList.remove('demo-signin');return renderBeforeDemoSignIn();};
const actionBeforeDemoSignIn=action;
action=async name=>{if(name==='enter-synthetic-workspace'){const next=demoRoles[demoRoleChoice]?demoRoleChoice:'Owner';workspaceRole=next;profile={...profile,role:next};demoEntered=true;view='overview';selected=null;log(`Entered the synthetic workspace as ${workspaceRole}. No credentials, customer data, or external systems were accessed.`);render();toast(`Local demo started as ${workspaceRole}.`);return;}if(name==='sign-out-demo'){const priorRole=workspaceRole;demoEntered=false;demoRoleChoice='Owner';workspaceRole='Owner';profile={...profile,role:'Owner'};selected=null;view='overview';document.querySelector('#dialog')?.close();log(`Signed out of the local ${priorRole} demo. No real account session existed.`);render();return;}if(!demoEntered){toast('Choose a local demo role to enter the synthetic workspace.');return;}return actionBeforeDemoSignIn(name);};
document.addEventListener('click',event=>{const button=event.target.closest('button[data-demo-role]');if(!button)return;const next=button.dataset.demoRole;if(!demoRoles[next])return;event.preventDefault();event.stopImmediatePropagation();demoRoleChoice=next;render();},true);
const accessGovernancePreview=()=>`<section class="demo-access-governance" aria-labelledby="access-governance-title"><header><span class="demo-governance-kicker">${icon('shield')} ORGANIZATION-CONTROLLED ACCESS</span><span class="demo-governance-state">${icon('lock')} DEFAULT DENY</span></header><h3 id="access-governance-title">Only named, approved people can access a live workspace.</h3><p>A company administrator provisions a specific <strong>Organization owner</strong> or <strong>Authorized lab assistant</strong>. Everyone else is denied before the workspace loads.</p><div class="demo-governance-controls"><article><span>${icon('server')}</span><div><strong>Company SSO</strong><small>OIDC or SAML identity provider</small></div></article><article><span>${icon('shield')}</span><div><strong>Authenticator required</strong><small>Passkey preferred; authenticator-app code supported</small></div></article><article><span>${icon('layers')}</span><div><strong>Tenant-bound role</strong><small>Server verifies organization, role, and session</small></div></article><article><span>${icon('activity')}</span><div><strong>Admin revocation</strong><small>Device or session access can be ended immediately</small></div></article></div><footer>${icon('eye')} This is a local portfolio preview. It does not send a phone code, store an authenticator secret, or grant real access.</footer></section>`;
const demoSignInBeforeAccessGovernance=demoSignIn;
demoSignIn=()=>demoSignInBeforeAccessGovernance().replace('<div class="demo-role-picker"',`${accessGovernancePreview()}<div class="demo-role-picker"`).replace('Choose the point of view you want to use for this browser-only demonstration.','Choose a local point of view for this browser-only demonstration. These are not login accounts.');
// This is a deployment-readiness status, not a pretend identity-provider flow.
// Keeping it static makes the boundary clear: a real company connects SSO on
// its server after the tenant, redirect URIs, MFA policy, and group mapping
// have been reviewed.
const companySsoReadiness=()=>`<section class="company-sso-readiness" aria-labelledby="company-sso-title"><header><div><span class="company-sso-kicker">${icon('server')} COMPANY SSO · PRODUCTION CONNECTION</span><h3 id="company-sso-title">SSO setup is required for a live deployment.</h3></div><span class="company-sso-state">${icon('lock')} NOT CONNECTED</span></header><p>TraceGuard can be connected through a company identity provider after an administrator reviews the tenant boundary, redirect addresses, MFA policy, and approved role groups.</p><div class="company-sso-options" aria-label="Supported production identity-provider patterns"><article><span>${icon('server')}</span><div><strong>Microsoft Entra ID</strong><small>OIDC or SAML · company-managed identity</small></div><b>${icon('check')} Ready to configure</b></article><article><span>${icon('shield')}</span><div><strong>Okta</strong><small>OIDC or SAML · company-managed identity</small></div><b>${icon('check')} Ready to configure</b></article></div><div class="company-sso-rule"><span>${icon('layers')} Only the <strong>Organization owner</strong> and <strong>Authorized lab assistant</strong> groups can be mapped in a live workspace.</span><button type="button" disabled aria-describedby="company-sso-local-note">${icon('lock')} Configure during deployment</button></div><p class="company-sso-local-note" id="company-sso-local-note">${icon('eye')} This local portfolio preview does not contact Entra, Okta, or any other company system. It cannot accept a password, MFA code, or SSO token.</p></section>`;
const demoSignInBeforeCompanySso=demoSignIn;
demoSignIn=()=>demoSignInBeforeCompanySso().replace('<div class="demo-role-picker"',`${companySsoReadiness()}<div class="demo-role-picker"`);
const profileAccessGovernance=()=>`<section class="profile-access-governance" aria-label="Access governance preview"><div><span class="eyebrow">${icon('shield')} ACCESS GOVERNANCE PREVIEW</span><h3>Live access is company-admin approved.</h3><p>Named Owner and Lab Assistant roles would use company SSO, an authenticator, tenant checks, and immediate session revocation.</p></div><span class="profile-governance-badge">${icon('lock')} Demo only</span></section>`;
const profileViewBeforeAccessGovernance=profileView;
profileView=()=>profileViewBeforeAccessGovernance().replace('<div class="profile-mini-note">',`${profileAccessGovernance()}<div class="profile-mini-note">`);
render();

// The builder card makes the portfolio's authorship visible without inventing
// personal details or treating a public profile as an account. It is kept in
// browser memory only: no profile field is sent, stored, or fetched.
const builderSkillOptions=['Python','SQL','JavaScript','Security design','UI/UX','API design','Threat modeling','Data privacy'];
const defaultBuilderProfile=()=>({name:'Sujal K Rao',headline:'Cybersecurity student developer',goal:'Building an evidence-first security portfolio that respects privacy, explains decisions, and earns trust.',github:'https://github.com/sujalrao061',linkedin:'https://www.linkedin.com/in/sujal-rao-709069432',skills:['Python','SQL','JavaScript','Security design','UI/UX']});
let builderProfile=defaultBuilderProfile();
const builderDisplayName=()=>builderProfile.name||profile.name||'Your name';
const builderDisplayHeadline=()=>builderProfile.headline||'Cybersecurity student developer';
const builderInitials=()=>builderDisplayName().trim().split(/\s+/).map(word=>Array.from(word)[0]).slice(0,2).join('').toUpperCase()||'SK';
const builderAvatar=()=>`<div class="avatar builder-profile-avatar" data-color="${profile.color}">${esc(builderInitials())}</div>`;
const builderProfileUrl=(value,provider)=>{
 const raw=String(value||'').trim();
 if(!raw)return '';
 let parsed;
 try{parsed=new URL(raw);}catch{throw new Error(`Enter a complete ${provider} URL beginning with https://.`);}
 const approved=provider==='GitHub'?['github.com','www.github.com']:['linkedin.com','www.linkedin.com'];
 if(parsed.protocol!=='https:'||!approved.includes(parsed.hostname.toLowerCase()))throw new Error(`Use your official ${provider} URL over https.`);
 return parsed.href;
};
const safeBuilderProfileUrl=(value,provider)=>{try{return builderProfileUrl(value,provider);}catch{return '';}};
function builderConnection(label,iconName,value,provider){const url=safeBuilderProfileUrl(value,provider);return url?`<a class="builder-connection is-ready" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${icon(iconName)}<span><small>${esc(label)}</small><strong>Open profile</strong></span>${icon('arrow')}<span class="sr-only">Opens your ${esc(label)} profile in a new tab</span></a>`:`<button class="builder-connection" type="button" data-action="edit-builder-profile">${icon(iconName)}<span><small>${esc(label)}</small><strong>Add your link</strong></span>${icon('arrow')}</button>`;}
function builderProfileCard(){const skills=builderProfile.skills.length?builderProfile.skills:defaultBuilderProfile().skills;return `<section class="builder-profile-card" aria-labelledby="builder-profile-title"><div class="builder-profile-intro"><span class="builder-profile-kicker">${icon('sparkles')} BUILT BY</span><div class="builder-profile-person">${builderAvatar()}<div><h2 id="builder-profile-title">${esc(builderDisplayName())}</h2><p>${esc(builderDisplayHeadline())}</p></div></div><p class="builder-profile-goal">${esc(builderProfile.goal)}</p></div><div class="builder-profile-work"><div><span class="builder-work-label">TECHNOLOGIES &amp; FOCUS</span><div class="builder-skill-list" aria-label="Skills used">${skills.map(skill=>`<span>${icon('check')}${esc(skill)}</span>`).join('')}</div></div><div class="builder-connections" aria-label="Builder profile links">${builderConnection('GitHub','code',builderProfile.github,'GitHub')}${builderConnection('LinkedIn','user',builderProfile.linkedin,'LinkedIn')}</div></div><div class="builder-profile-actions"><button class="builder-profile-edit" type="button" data-action="edit-builder-profile">${icon('sliders')}Customize card</button><p>${icon('lock')}Local and session-only. No link is prefilled or opened automatically.</p></div></section>`;}
function builderProfileDialog(){const skills=builderProfile.skills.length?builderProfile.skills:defaultBuilderProfile().skills;openDialog('Personalize your builder card',`<p class="dialog-intro">This card helps a professor, recruiter, or owner connect this project with you. Changes stay in this browser session and are never sent anywhere.</p><div class="builder-profile-form"><div class="form-grid"><div class="form-field"><label for="builder-name">${icon('user')}Your name</label><input class="field" id="builder-name" value="${esc(builderProfile.name)}" maxlength="60" autocomplete="name" placeholder="Use the name you want recruiters to see"></div><div class="form-field"><label for="builder-headline">${icon('shield')}Headline</label><input class="field" id="builder-headline" value="${esc(builderProfile.headline)}" maxlength="72" autocomplete="off" placeholder="Cybersecurity student developer"></div><div class="form-field wide"><label for="builder-goal">${icon('target')}Project goal</label><textarea class="field" id="builder-goal" maxlength="180" placeholder="What are you building and why?">${esc(builderProfile.goal)}</textarea></div><div class="form-field"><label for="builder-github">${icon('code')}GitHub URL <small>optional</small></label><input class="field" id="builder-github" value="${esc(builderProfile.github)}" inputmode="url" autocomplete="url" placeholder="https://github.com/your-handle"></div><div class="form-field"><label for="builder-linkedin">${icon('user')}LinkedIn URL <small>optional</small></label><input class="field" id="builder-linkedin" value="${esc(builderProfile.linkedin)}" inputmode="url" autocomplete="url" placeholder="https://www.linkedin.com/in/your-handle"></div></div><fieldset class="builder-skill-picker"><legend>${icon('layers')}Skills used in this project</legend><p>Choose up to six skills that best describe your work.</p><div>${builderSkillOptions.map(skill=>`<label><input type="checkbox" class="builder-skill-choice" value="${esc(skill)}" ${skills.includes(skill)?'checked':''}><span>${esc(skill)}</span></label>`).join('')}</div></fieldset></div><p id="builder-profile-error" class="error" role="alert"></p><div class="form-actions builder-profile-dialog-actions">${btn('Reset local card','reset-builder-profile','refresh')}${btn('Save builder card','save-builder-profile','check',true)}</div>`);}
const demoSignInBeforeBuilderProfile=demoSignIn;
demoSignIn=()=>demoSignInBeforeBuilderProfile().replace('</section></main></div>',`</section>${builderProfileCard()}</main></div>`);
const actionBeforeBuilderProfile=action;
action=async name=>{
 if(name==='edit-builder-profile'){builderProfileDialog();return;}
 if(name==='reset-builder-profile'){builderProfile=defaultBuilderProfile();builderProfileDialog();toast('Builder card reset to local defaults.');return;}
 if(name==='save-builder-profile'){
  const error=document.querySelector('#builder-profile-error');
  const name=document.querySelector('#builder-name')?.value.trim()||'';
  const headline=document.querySelector('#builder-headline')?.value.trim()||'';
  const goal=document.querySelector('#builder-goal')?.value.trim()||'';
  const github=document.querySelector('#builder-github')?.value.trim()||'';
  const linkedin=document.querySelector('#builder-linkedin')?.value.trim()||'';
  const skills=[...document.querySelectorAll('.builder-skill-choice:checked')].map(node=>node.value).filter(skill=>builderSkillOptions.includes(skill));
  try{
   if(name&&Array.from(name).length>60)throw new Error('Keep your name to 60 characters or fewer.');
   if(headline&&Array.from(headline).length>72)throw new Error('Keep the headline to 72 characters or fewer.');
   if(!goal)throw new Error('Add a short project goal so visitors know what you are building.');
   if(Array.from(goal).length>180)throw new Error('Keep the project goal to 180 characters or fewer.');
   if(!skills.length)throw new Error('Choose at least one skill for the builder card.');
   if(skills.length>6)throw new Error('Choose no more than six skills for the builder card.');
   builderProfile={name,headline,goal,github:builderProfileUrl(github,'GitHub'),linkedin:builderProfileUrl(linkedin,'LinkedIn'),skills};
  }catch(message){if(error)error.textContent=message instanceof Error?message.message:String(message);return;}
  document.querySelector('#dialog')?.close();
  log('Updated the local Builder profile card. No personal profile data was sent.');
  render();
  toast('Builder card saved for this browser session.');
  return;
 }
 if(name==='replace:clear')builderProfile=defaultBuilderProfile();
 return actionBeforeBuilderProfile(name);
};
render();

// Access governance is intentionally a local policy walkthrough. These values
// never represent people, accounts, devices, or permissions outside this tab.
titles['access-governance']='Access governance';
const governancePreview={
 request:{id:'REQ-204',identity:'demo-access-request',role:'Lab assistant',status:'Awaiting owner decision',stage:'Requested'},
 assistant:{identity:'demo-lab-assistant',revoked:false}
};
const governanceAudit=[
 {at:new Date().toISOString(),actor:'Local preview',text:'Access governance preview initialized with default-deny policy.',icon:'lock'},
 {at:new Date(Date.now()-1000*60*7).toISOString(),actor:'Policy baseline',text:'Only Owner and Lab assistant roles are eligible after organization approval.',icon:'shield'},
 {at:new Date(Date.now()-1000*60*16).toISOString(),actor:'Deployment gate',text:'Company SSO connection remains not connected in this local portfolio build.',icon:'server'}
];
function governanceNote(text,icon='activity'){governanceAudit.unshift({at:new Date().toISOString(),actor:'Local owner preview',text,icon});if(governanceAudit.length>12)governanceAudit.pop();log(`Access governance preview: ${text}`);}
function governanceStatus(text,tone='neutral'){return `<span class="access-status ${tone}">${icon(tone==='good'?'check':tone==='warn'?'clock':tone==='danger'?'lock':'shield')}${esc(text)}</span>`;}
function governanceSteps(){const stage=governancePreview.request.stage;const stages=[['Requested','A named request is submitted for review.','file'],['Identity checked','Company SSO verifies tenant membership.','server'],['MFA confirmed','Passkey or authenticator-app policy is met.','shield'],['Owner approved','An authorized owner records the decision.','check'],['Server grants','The server maps the approved role and logs it.','lock']];const approved=stage==='Policy approved';return `<section class="access-lifecycle" aria-labelledby="access-lifecycle-title"><header><div><span class="eyebrow">${icon('layers')} APPROVAL LIFECYCLE</span><h2 id="access-lifecycle-title">A role is earned in five visible steps.</h2><p>A browser interface cannot grant access. In production, the identity provider and application server enforce every step.</p></div>${governanceStatus(approved?'POLICY PREVIEW APPROVED':'DEFAULT DENY','good')}</header><ol>${stages.map(([title,description,ico],index)=>{const complete=approved&&index<4;const current=!approved&&index===0;return `<li class="${complete?'complete':''} ${current?'current':''}"><span>${icon(complete?'check':ico)}</span><div><small>${String(index+1).padStart(2,'0')}</small><strong>${esc(title)}</strong><p>${esc(description)}</p></div></li>`;}).join('')}</ol><p class="access-lifecycle-note">${icon('eye')}The approval shown here is a session-only policy example. It does not create an account, group membership, session, password, or MFA enrollment.</p></section>`;}
function accessRequestCard(isOwner){const request=governancePreview.request;const pending=request.status==='Awaiting owner decision';const approved=request.stage==='Policy approved';const denied=request.stage==='Denied';const actionArea=!isOwner?`<p class="access-read-only">${icon('lock')}Only the Owner local view can simulate a decision. A real service would verify this on the server.</p>`:pending?`<div class="access-card-actions">${btn('Approve policy preview','governance-approve-request','check',true)}${btn('Keep default deny','governance-deny-request','lock')}</div>`:approved?`<div class="access-read-only">${icon('check')}Policy preview recorded. A real server would still need to map SSO groups and enforce the role before access exists.</div>`:`<div class="access-card-actions">${btn('Restore request for demo','governance-reset-request','refresh')}</div>`;return `<section class="access-request-card" aria-labelledby="access-request-title"><div class="access-section-head"><div><span class="eyebrow">${icon('file')} ACCESS REQUEST · SYNTHETIC EXAMPLE</span><h2 id="access-request-title">Review a named role request.</h2></div>${governanceStatus(request.status,pending?'warn':approved?'good':'danger')}</div><div class="access-request-body"><div class="access-request-identity"><span>${icon('user')}</span><div><small>REQUEST ID · ${esc(request.id)}</small><strong>${esc(request.identity)}</strong><p>Requested role: <b>${esc(request.role)}</b> · synthetic identity fixture</p></div></div><dl><div><dt>Tenant check</dt><dd>${pending?'Not started in local preview':approved?'Would be required server-side':'No request is eligible'}</dd></div><div><dt>MFA policy</dt><dd>Passkey or authenticator app required</dd></div><div><dt>Authority</dt><dd>Organization Owner only</dd></div></dl>${actionArea}</div></section>`;}
function accessRoster(isOwner){const revoked=governancePreview.assistant.revoked;return `<section class="access-roster" aria-labelledby="access-roster-title"><div class="access-section-head"><div><span class="eyebrow">${icon('user')} APPROVED ROLE REGISTER</span><h2 id="access-roster-title">Least privilege, visible ownership.</h2></div><span class="access-count">2 allowed policy roles</span></div><div class="access-roster-list"><article class="access-person"><span class="access-person-icon">${icon('shield')}</span><div class="access-person-main"><small>SYNTHETIC POLICY RECORD</small><strong>demo-owner</strong><p>Organization Owner · access approval, security direction, emergency review</p></div>${governanceStatus('Protected owner role','good')}<div class="access-person-control"><button class="access-disabled" type="button" disabled>${icon('lock')}Last Owner protected</button><small>Production policy should prevent removing the final organization owner.</small></div></article><article class="access-person ${revoked?'revoked':''}"><span class="access-person-icon">${icon('activity')}</span><div class="access-person-main"><small>SYNTHETIC POLICY RECORD</small><strong>${esc(governancePreview.assistant.identity)}</strong><p>Lab assistant · evidence review only; cannot administer tenants, roles, or connectors</p></div>${governanceStatus(revoked?'Revoked local example':'Approved policy example',revoked?'danger':'good')}<div class="access-person-control">${isOwner?btn(revoked?'Restore local policy example':'Simulate access removal',revoked?'governance-restore-assistant':'governance-revoke-assistant',revoked?'refresh':'lock',!revoked):`<span class="access-read-only">${icon('eye')}Read-only local role view</span>`}<small>${revoked?'No live session exists or was ended.':'A production removal revokes active server sessions and writes a durable audit record.'}</small></div></article></div></section>`;}
function accessAudit(){return `<section class="access-audit" aria-labelledby="access-audit-title"><div class="access-section-head"><div><span class="eyebrow">${icon('activity')} AUDIT SNAPSHOT · LOCAL DEMO</span><h2 id="access-audit-title">Every access decision leaves a reason.</h2></div><span class="access-count">Session-only entries</span></div><div class="access-audit-list">${governanceAudit.slice(0,5).map(entry=>`<article><span>${icon(entry.icon)}</span><div><strong>${esc(entry.actor)}</strong><p>${esc(entry.text)}</p></div><time>${time(entry.at)} UTC</time></article>`).join('')}</div><p class="access-audit-note">${icon('lock')}This list resets with the browser session. A live deployment needs append-only, tenant-scoped audit storage with retention and review controls.</p></section>`;}
function accessGovernanceView(){const isOwner=workspaceRole==='Owner';return heading('Access governance','A practical view of who may receive access, how approval works, and how access is removed.',isOwner?btn('Reset local preview','governance-reset','refresh'):btn('Return to overview','overview','grid'))+`<section class="access-governance-hero" aria-labelledby="access-governance-heading"><div class="access-hero-copy"><span class="eyebrow">${icon('shield')} ORGANIZATION ACCESS · LOCAL POLICY PREVIEW</span><h1 id="access-governance-heading">Access starts with an <em>approved identity.</em></h1><p>TraceGuard’s live model is default deny: a company administrator must approve a named Owner or Lab assistant after company SSO and MFA checks. This page demonstrates the workflow without pretending to administer a real system.</p><div class="access-hero-rule"><span>${icon('lock')}</span><div><strong>Server-enforced in production</strong><small>Tenant boundary, role mapping, session lifecycle, and audit records must be verified outside the browser.</small></div></div></div><div class="access-hero-summary"><article><span>${icon('user')}</span><small>Eligible roles</small><strong>2</strong><p>Owner + Lab assistant</p></article><article><span>${icon('file')}</span><small>Open sample</small><strong>${governancePreview.request.stage==='Requested'?'1':'0'}</strong><p>awaiting owner decision</p></article><article><span>${icon('shield')}</span><small>Authenticator</small><strong>Required</strong><p>passkey preferred</p></article><article><span>${icon('server')}</span><small>Live connection</small><strong>0</strong><p>not connected</p></article></div><p class="access-hero-disclaimer">${icon('eye')}The records and actions on this page are synthetic and session-only. No employee, company account, authenticator, phone number, device, or session is contacted.</p></section>${!isOwner?`<section class="access-role-boundary"><span>${icon('lock')}</span><div><span class="eyebrow">READ-ONLY ROLE BOUNDARY</span><h2>Lab assistants can review evidence, not administer access.</h2><p>You are viewing the local ${esc(workspaceRole)} role. In a real deployment, the server must reject access-governance changes unless the identity has the Owner role for the current tenant.</p></div>${btn('View Owner policy example','governance-switch-owner','shield')}</section>`:''}<div class="access-governance-grid">${accessRequestCard(isOwner)}${accessRoster(isOwner)}</div>${governanceSteps()}${accessAudit()}<section class="access-production-gate"><div><span class="eyebrow">${icon('server')} BEFORE A COMPANY GOES LIVE</span><h2>Make the protection real before connecting people or data.</h2><p>Connect an approved identity provider only after configuration review, tenant-scoped authorization testing, monitored audit storage, and a documented response plan.</p></div><ul><li>${icon('check')}Company SSO with tenant-specific group mapping</li><li>${icon('check')}Passkey or authenticator-app MFA policy</li><li>${icon('check')}Server-side revocation, audit logs, rate limits, and monitoring</li></ul></section>`;}

const sidebarBeforeAccessGovernance=sidebar;
sidebar=()=>sidebarBeforeAccessGovernance().replace('</nav><div class="sidebar-bottom">',`<button data-nav="access-governance" class="${view==='access-governance'?'active':''}" ${view==='access-governance'?'aria-current="page"':''}>${icon('shield')}Access governance</button></nav><div class="sidebar-bottom">`);
const renderBeforeAccessGovernance=render;
function renderAccessGovernance(){document.documentElement.dataset.theme=profile.theme;document.documentElement.dataset.accent=profile.accent;document.body.classList.toggle('compact',profile.compact);document.querySelector('#app').innerHTML=`<div class="layout">${sidebar()}<div class="page"><header class="topbar"><div class="breadcrumb"><button class="mobile-menu" aria-label="Toggle navigation" data-action="menu">${icon('menu')}</button><span>Workspace</span><span>/</span><strong>${titles[view]}</strong></div><div class="top-actions"><button class="quick-launch" data-action="quick-actions" aria-label="Open quick actions">${icon('bolt')}<span>Quick actions</span></button><button class="search-launch" data-action="search">${icon('search')}Search alerts <kbd>Ctrl K</kbd></button><span class="pill green"><span class="dot"></span>Synthetic lab</span><button class="icon-button" data-action="activity-panel" aria-label="Workspace activity">${icon('bell')}</button><button class="profile-trigger" data-nav="profile" aria-label="Open my profile">${avatar()}</button></div></header><main class="main" id="main" tabindex="-1">${accessGovernanceView()}<footer class="footer"><span>${icon('lock')}Session-only data · No model connection</span><span>TraceGuard / Security investigation lab <span class="mono">v0.1</span></span></footer></main></div></div>`;applyStyles();}
render=()=>{if(!demoEntered||view!=='access-governance')return renderBeforeAccessGovernance();return renderAccessGovernance();};
const actionBeforeAccessGovernance=action;
action=async name=>{const ownerOnly=['governance-approve-request','governance-deny-request','governance-reset-request','governance-revoke-assistant','governance-restore-assistant','governance-reset'];if(ownerOnly.includes(name)&&workspaceRole!=='Owner'){toast('Only the Owner local view can simulate access governance.');return;}if(name==='governance-approve-request'){governancePreview.request.status='Policy preview approved';governancePreview.request.stage='Policy approved';governanceNote(`Approved ${governancePreview.request.id} as a local policy preview; no role or access was granted.`,'check');render();toast('Policy preview approved locally. No real access was created.');return;}if(name==='governance-deny-request'){governancePreview.request.status='Default deny retained';governancePreview.request.stage='Denied';governanceNote(`Retained default deny for ${governancePreview.request.id}; no access was created.`,'lock');render();toast('Default deny retained in the local preview.');return;}if(name==='governance-reset-request'){governancePreview.request.status='Awaiting owner decision';governancePreview.request.stage='Requested';governanceNote(`Restored ${governancePreview.request.id} as a pending synthetic request.`,'refresh');render();toast('Synthetic request restored for the local demo.');return;}if(name==='governance-revoke-assistant'){governancePreview.assistant.revoked=true;governanceNote('Simulated Lab assistant access removal. No account or session was changed.','lock');render();toast('Local removal preview recorded; no real account was affected.');return;}if(name==='governance-restore-assistant'){governancePreview.assistant.revoked=false;governanceNote('Restored the Lab assistant policy example in this browser session.','refresh');render();toast('Local policy example restored.');return;}if(name==='governance-reset'){governancePreview.request.status='Awaiting owner decision';governancePreview.request.stage='Requested';governancePreview.assistant.revoked=false;governanceNote('Reset the local access-governance demonstration to its default policy state.','refresh');render();toast('Local governance preview reset.');return;}if(name==='governance-switch-owner'){workspaceRole='Owner';profile={...profile,role:'Owner'};governanceNote('Changed to the Owner local policy view.','shield');render();toast('Viewing the Owner policy example.');return;}if(name.startsWith('replace:')){governancePreview.request.status='Awaiting owner decision';governancePreview.request.stage='Requested';governancePreview.assistant.revoked=false;}return actionBeforeAccessGovernance(name);};
if(document.modelContext?.registerTool){const controller=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'list_lab_alerts',title:'List synthetic lab alerts',description:'Read the current synthetic alert list. Does not export notes or source addresses.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('Expected an empty object.');return {alerts:alerts.map(({id,title,severity,status})=>({id,title,severity,status}))};}},{signal:controller.signal})).catch(()=>{});window.addEventListener('pagehide',()=>controller.abort(),{once:true});}catch{}}

// The Owner Control Center is deliberately a deployment-readiness workspace,
// not a simulated production console. Its switches and review records stay in
// browser memory, so they can demonstrate the decisions an owner should make
// without suggesting that an identity provider, backup, notification, or
// monitoring system is connected.
titles['owner-control-center']='Owner control center';
const ownerControlState={reviewed:new Set(),audit:[
 {at:new Date().toISOString(),actor:'Local owner center',text:'Opened deployment-readiness preview. No company system is connected.',icon:'eye'},
 {at:new Date(Date.now()-1000*60*11).toISOString(),actor:'Production boundary',text:'Live SSO, audit storage, monitoring, backups, and notifications remain deployment requirements.',icon:'lock'}
]};
const ownerControlGates=[
 {id:'identity',icon:'shield',title:'Identity & access',owner:'Organization Owner + IT',description:'Connect company SSO, enforce MFA, map tenant roles, and test immediate session revocation.'},
 {id:'audit',icon:'file',title:'Audit & evidence',owner:'Security lead',description:'Confirm append-only, tenant-scoped audit retention and a review path before any customer events arrive.'},
 {id:'monitoring',icon:'activity',title:'Monitoring & response',owner:'Operations owner',description:'Configure alert routing, escalation ownership, rate-limit visibility, and incident response coverage.'},
 {id:'recovery',icon:'database',title:'Backup & recovery',owner:'Platform owner',description:'Prove encrypted backups, recovery objectives, and a documented restore drill with evidence.'},
 {id:'rollout',icon:'compass',title:'People & rollout',owner:'Executive sponsor',description:'Name the pilot owner, train approved users, agree success measures, and set stop/go criteria.'}
];
function ownerControlNote(text,icon='activity'){ownerControlState.audit.unshift({at:new Date().toISOString(),actor:'Local owner preview',text,icon});if(ownerControlState.audit.length>10)ownerControlState.audit.pop();log(`Owner Control Center preview: ${text}`);}
function ownerControlGateState(gate){return ownerControlState.reviewed.has(gate.id)?['LOCAL PLAN REVIEWED','reviewed']:['REQUIRED BEFORE LAUNCH','required'];}
function ownerControlStatus(text,tone='neutral'){return `<span class="owner-control-status ${tone}">${icon(tone==='reviewed'?'check':tone==='required'?'lock':'eye')}${esc(text)}</span>`;}
function ownerControlGate(gate,isOwner){const [label,tone]=ownerControlGateState(gate);const reviewed=ownerControlState.reviewed.has(gate.id);const control=!isOwner?`<span class="owner-control-readonly">${icon('eye')}Owner-only local planning action</span>`:reviewed?`<span class="owner-control-reviewed-note">${icon('check')}Plan review recorded locally. Live verification is still required.</span>`:btn('Review local plan',`owner-control-review:${gate.id}`,'check',true);return `<article class="owner-control-gate ${reviewed?'is-reviewed':''}"><div class="owner-control-gate-top"><span class="owner-control-gate-icon">${icon(gate.icon)}</span>${ownerControlStatus(label,tone)}</div><small>${esc(gate.owner)}</small><h3>${esc(gate.title)}</h3><p>${esc(gate.description)}</p><footer>${control}</footer></article>`;}
function ownerControlHealth(){const items=[
 ['server','Identity provider','Not connected','Company SSO must be configured by the customer administrator.','required'],
 ['activity','Monitoring','Not active','No live API, collector, telemetry, or paging connection exists in this lab.','required'],
 ['file','Audit storage','Session-only','The prototype does not retain a compliance audit record after the browser session.','required'],
 ['database','Recovery evidence','Not demonstrated','A hosted deployment needs backups plus a tested, documented restore process.','required']
 ];return `<section class="owner-health" aria-labelledby="owner-health-title"><div class="owner-health-intro"><span class="eyebrow">${icon('activity')} SYSTEM HEALTH · TRUTHFUL STATUS</span><h2 id="owner-health-title">Know what is connected <em>before</em> you trust it.</h2><p>These statuses identify the production controls a company must operate. They are not health claims about this browser-only portfolio build.</p><div class="owner-health-boundary">${icon('lock')}<span>0 customer systems · 0 live credentials · 0 background services</span></div></div><div class="owner-health-grid">${items.map(([ico,label,state,description,tone])=>`<article><span>${icon(ico)}</span><div><small>${esc(label)}</small><strong>${esc(state)}</strong><p>${esc(description)}</p></div>${ownerControlStatus('Deployment gate',tone)}</article>`).join('')}</div></section>`;}
function ownerControlNotifications(isOwner){const plans=[
 ['shield','Access-risk policy','Owner review for SSO failures, unexpected privilege change, or emergency revocation.'],
 ['activity','Critical-case policy','Named human escalation path for evidence-backed critical cases and response targets.'],
 ['database','Recovery policy','Visible owner decision when backup or restore verification fails.']
 ];const reviewed=ownerControlState.reviewed.has('notifications');return `<section class="owner-notification-plan" aria-labelledby="owner-notification-title"><header><div><span class="eyebrow">${icon('bell')} NOTIFICATION & ESCALATION PLAN</span><h2 id="owner-notification-title">A serious owner expects to hear about the right things.</h2><p>These are notification requirements for a real deployment. This page cannot page, email, text, or contact any person.</p></div>${ownerControlStatus(reviewed?'LOCAL PLAN REVIEWED':'NO NOTIFICATION INTEGRATION',reviewed?'reviewed':'required')}</header><div class="owner-notification-list">${plans.map(([ico,title,description])=>`<article><span>${icon(ico)}</span><div><strong>${esc(title)}</strong><p>${esc(description)}</p></div><small>Production configuration required</small></article>`).join('')}</div><footer>${isOwner?(reviewed?`<span class="owner-control-reviewed-note">${icon('check')}Local notification plan reviewed. No recipient or delivery rule was created.</span>`:btn('Review notification plan','owner-control-review:notifications','check',true)):`<span class="owner-control-readonly">${icon('eye')}Owner-only local planning action</span>`}</footer></section>`;}
function ownerControlAudit(){return `<section class="owner-control-audit" aria-labelledby="owner-control-audit-title"><header><div><span class="eyebrow">${icon('file')} OWNER DECISION SNAPSHOT · LOCAL ONLY</span><h2 id="owner-control-audit-title">Keep the readiness conversation visible.</h2></div><span class="owner-control-count">${ownerControlState.audit.length} session entries</span></header><div class="owner-control-audit-list">${ownerControlState.audit.slice(0,5).map(entry=>`<article><span>${icon(entry.icon)}</span><div><strong>${esc(entry.actor)}</strong><p>${esc(entry.text)}</p></div><time>${time(entry.at)} UTC</time></article>`).join('')}</div><p>${icon('lock')}This is a browser-session planning note. A live company deployment needs durable, tamper-evident audit storage with retention and access review.</p></section>`;}
function ownerControlCenterView(){const isOwner=workspaceRole==='Owner';const reviewed=ownerControlState.reviewed.size;return heading('Owner control center','The decisions, evidence, and operational gates a company owner should expect before a rollout.',isOwner?btn('Reset local plan','owner-control-reset','refresh'):btn('Return to overview','overview','grid'))+`<section class="owner-control-hero" aria-labelledby="owner-control-title"><div class="owner-control-copy"><span class="eyebrow">${icon('radar')} OWNER OPERATIONS · LOCAL READINESS PREVIEW</span><h1 id="owner-control-title">Turn a promising security product into a <em>trusted rollout.</em></h1><p>An owner needs more than a polished dashboard. They need a clear record of who controls access, what the system is connected to, how critical issues escalate, and how recovery is proven.</p><div class="owner-control-actions">${btn('Review access governance','access-governance','shield',true)}${btn('Open privacy boundary','privacy','lock')}</div><p class="owner-control-disclaimer">${icon('eye')}Every control on this page is a local planning preview. It cannot connect SSO, enable monitoring, create a backup, contact a team member, or change a company system.</p></div><div class="owner-control-summary" aria-label="Owner readiness summary"><article><span>${icon('server')}</span><small>Live connections</small><strong>0</strong><p>no company system connected</p></article><article><span>${icon('layers')}</span><small>Launch gates</small><strong>${ownerControlGates.length}</strong><p>must be evidenced before launch</p></article><article><span>${icon('checklist')}</span><small>Local plans reviewed</small><strong>${reviewed}</strong><p>planning only, not verification</p></article><article><span>${icon('shield')}</span><small>Access model</small><strong>Default deny</strong><p>Owner + Lab assistant policy</p></article></div></section>${!isOwner?`<section class="owner-control-role-boundary">${icon('lock')}<div><span class="eyebrow">READ-ONLY ROLE BOUNDARY</span><h2>Lab assistants can inspect readiness, not change it.</h2><p>The current local role is ${esc(workspaceRole)}. A real system must enforce Owner authority on the server for every operational decision.</p></div></section>`:''}${ownerControlHealth()}<section class="owner-control-gates" aria-labelledby="owner-control-gates-title"><header><div><span class="eyebrow">${icon('checklist')} OWNER LAUNCH GATES</span><h2 id="owner-control-gates-title">Five things I would ask to see before I sign off.</h2><p>Reviewing a local plan is useful for a demo. It never replaces real integration testing, security evidence, or company approval.</p></div><span class="owner-control-count">${reviewed} local reviews</span></header><div class="owner-control-gate-grid">${ownerControlGates.map(gate=>ownerControlGate(gate,isOwner)).join('')}</div></section>${ownerControlNotifications(isOwner)}${ownerControlAudit()}<section class="owner-control-rollout"><div><span class="eyebrow">${icon('compass')} FIRST 30 DAYS</span><h2>Start with an owned, reversible pilot.</h2><p>Connect no live data until the company approves the boundary. Begin with test fixtures, review evidence quality, then document the stop/go decision with the executive sponsor.</p></div><ol><li><span>01</span><strong>Agree the boundary</strong><small>Owner, source scope, retention, escalation</small></li><li><span>02</span><strong>Prove controls</strong><small>SSO, roles, audit, monitoring, recovery</small></li><li><span>03</span><strong>Run a contained pilot</strong><small>Test tenant, human review, measurable outcome</small></li></ol></section>`;}

const sidebarBeforeOwnerControlCenter=sidebar;
sidebar=()=>sidebarBeforeOwnerControlCenter().replace('</nav><div class="sidebar-bottom">',`<button data-nav="owner-control-center" class="${view==='owner-control-center'?'active':''}" ${view==='owner-control-center'?'aria-current="page"':''}>${icon('radar')}Owner control center</button></nav><div class="sidebar-bottom">`);
const renderBeforeOwnerControlCenter=render;
function renderOwnerControlCenter(){document.documentElement.dataset.theme=profile.theme;document.documentElement.dataset.accent=profile.accent;document.body.classList.toggle('compact',profile.compact);document.querySelector('#app').innerHTML=`<div class="layout">${sidebar()}<div class="page"><header class="topbar"><div class="breadcrumb"><button class="mobile-menu" aria-label="Toggle navigation" data-action="menu">${icon('menu')}</button><span>Workspace</span><span>/</span><strong>${titles[view]}</strong></div><div class="top-actions"><button class="quick-launch" data-action="quick-actions" aria-label="Open quick actions">${icon('bolt')}<span>Quick actions</span></button><button class="search-launch" data-action="search">${icon('search')}Search alerts <kbd>Ctrl K</kbd></button><span class="pill green"><span class="dot"></span>Synthetic lab</span><button class="icon-button" data-action="activity-panel" aria-label="Workspace activity">${icon('bell')}</button><button class="profile-trigger" data-nav="profile" aria-label="Open my profile">${avatar()}</button></div></header><main class="main" id="main" tabindex="-1">${ownerControlCenterView()}<footer class="footer"><span>${icon('lock')}Session-only data · No model connection</span><span>TraceGuard / Security investigation lab <span class="mono">v0.1</span></span></footer></main></div></div>`;applyStyles();}
render=()=>{if(!demoEntered||view!=='owner-control-center')return renderBeforeOwnerControlCenter();return renderOwnerControlCenter();};
const actionBeforeOwnerControlCenter=action;
action=async name=>{if(name==='owner-control-reset'){if(workspaceRole!=='Owner'){toast('Only the Owner local view can reset readiness planning.');return;}ownerControlState.reviewed.clear();ownerControlNote('Reset local rollout plan reviews. No deployment or company setting changed.','refresh');render();toast('Local readiness plan reset.');return;}if(name.startsWith('owner-control-review:')){if(workspaceRole!=='Owner'){toast('Only the Owner local view can review readiness plans.');return;}const id=name.split(':')[1];const gate=id==='notifications'?{id:'notifications',title:'Notification & escalation'}:ownerControlGates.find(item=>item.id===id);if(!gate)return;ownerControlState.reviewed.add(gate.id);ownerControlNote(`Reviewed the ${gate.title} plan locally. No live control was configured or verified.`,gate.icon||'bell');render();toast(`${gate.title} plan marked reviewed locally.`);return;}return actionBeforeOwnerControlCenter(name);};

// The Owner Tour is a guided, browser-only walkthrough. It only navigates
// among synthetic views; it never investigates, imports, downloads, changes
// a role on a server, or activates a production control.
const ownerTourSteps=[
 {id:'overview',view:'overview',target:'.command-center',icon:'radar',eyebrow:'01 · SECURITY OVERVIEW',title:'Begin with the security picture.',copy:'An owner should see what needs attention, who is responsible, and the data boundary before making a decision.'},
 {id:'evidence',view:'detail',target:'.evidence-assistant',icon:'file',eyebrow:'02 · PRIORITY ALERT & EVIDENCE',title:'A priority signal needs cited facts.',copy:'This local case connects a priority alert to its synthetic event evidence. A severity label starts a review; it never proves an incident by itself.'},
 {id:'containment',view:'detail',target:'.account-containment',icon:'shield',eyebrow:'03 · HUMAN DECISION & SAFE CONTAINMENT',title:'Containment follows a verified human decision.',copy:'TraceGuard makes the safe response sequence visible. This tour does not reset a password, revoke a session, contact a device, or change any account.'},
 {id:'governance',view:'access-governance',target:'.access-governance-hero',icon:'layers',eyebrow:'04 · ACCESS GOVERNANCE',title:'Access begins with an approved identity.',copy:'A real rollout needs company SSO, MFA, tenant-scoped roles, server-side enforcement, and a durable reason for every access decision.'},
 {id:'owner-center',view:'owner-control-center',target:'.owner-control-hero',icon:'checklist',eyebrow:'05 · OWNER CONTROL CENTER',title:'A polished dashboard still needs launch proof.',copy:'The owner center names the controls, evidence, and accountable people a company should require before connecting data or beginning a pilot.'}
];
const ownerTourState={active:false,index:0,alertId:null,returnSelector:'[data-action="start-owner-tour"]'};
function ownerTourCurrent(){return ownerTourSteps[ownerTourState.index]||ownerTourSteps[0];}
function ownerTourAlert(){const chosen=alerts.find(alert=>alert.id===ownerTourState.alertId);return chosen||alerts.find(alert=>alert.severity==='critical'&&alert.status!=='Resolved')||alerts.find(alert=>alert.status!=='Resolved')||alerts[0]||null;}
function ownerTourOverlay(){const step=ownerTourCurrent(),index=ownerTourState.index,last=index===ownerTourSteps.length-1;return `<div class="owner-tour-layer" id="owner-tour-layer"><div class="owner-tour-scrim" aria-hidden="true"></div><aside class="owner-tour" id="owner-tour" role="dialog" aria-modal="true" aria-labelledby="owner-tour-title" aria-describedby="owner-tour-copy owner-tour-boundary"><header class="owner-tour-header"><div class="owner-tour-ident"><span class="owner-tour-icon">${icon(step.icon)}</span><div><span class="owner-tour-kicker">90-SECOND OWNER TOUR</span><strong>Step ${index+1} of ${ownerTourSteps.length}</strong></div></div><button class="owner-tour-skip" type="button" data-action="tour-skip" aria-label="Skip the Owner Tour">Skip ${icon('close')}</button></header><ol class="owner-tour-progress" aria-label="Owner Tour progress: step ${index+1} of ${ownerTourSteps.length}">${ownerTourSteps.map((item,itemIndex)=>`<li class="${itemIndex===index?'is-current':''} ${itemIndex<index?'is-complete':''}" aria-current="${itemIndex===index?'step':'false'}"><span>${itemIndex<index?icon('check'):String(itemIndex+1).padStart(2,'0')}</span><small class="sr-only">${esc(item.title)}</small></li>`).join('')}</ol><section class="owner-tour-step" aria-live="polite"><span class="owner-tour-step-label">${icon(step.icon)}${esc(step.eyebrow)}</span><h2 id="owner-tour-title">${esc(step.title)}</h2><p id="owner-tour-copy">${esc(step.copy)}</p></section><p class="owner-tour-boundary" id="owner-tour-boundary">${icon('lock')}Synthetic, local, and read-only: this guided demo has no live connection and makes no security, account, device, or data change.</p><footer class="owner-tour-actions">${index?`<button class="owner-tour-back" type="button" data-action="tour-back">${icon('arrow')}Back</button>`:`<span class="owner-tour-start-note">${icon('eye')}Guided tour only</span>`}<button class="owner-tour-next" type="button" data-action="${last?'tour-finish':'tour-next'}">${last?'Finish & explore':'Next'}${icon(last?'check':'arrow')}</button></footer></aside></div>`;}
function ownerTourMount({focus=true}={}){const app=document.querySelector('#app');if(app)app.inert=ownerTourState.active;document.querySelector('#owner-tour-layer')?.remove();document.querySelectorAll('.owner-tour-target').forEach(node=>node.classList.remove('owner-tour-target'));if(!ownerTourState.active)return;document.body.insertAdjacentHTML('beforeend',ownerTourOverlay());const step=ownerTourCurrent(),target=document.querySelector(step.target);target?.classList.add('owner-tour-target');requestAnimationFrame(()=>{target?.scrollIntoView({block:'start',behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});if(focus)document.querySelector('.owner-tour-next')?.focus({preventScroll:true});});}
function ownerTourRoute(index,{focus=true}={}){ownerTourState.index=Math.max(0,Math.min(ownerTourSteps.length-1,index));const step=ownerTourCurrent(),alert=ownerTourAlert();if(step.view==='detail'&&alert){ownerTourState.alertId=alert.id;selected=alert.id;}const nextView=step.view==='detail'&&!alert?'alerts':step.view;navigate(nextView);ownerTourMount({focus});}
function startOwnerTour(){ownerTourState.active=true;ownerTourState.index=0;ownerTourState.alertId=ownerTourAlert()?.id||null;ownerTourState.returnSelector='[data-action="start-owner-tour"]';if(!demoEntered){demoEntered=true;demoRoleChoice='Owner';workspaceRole='Owner';profile={...profile,role:'Owner'};log('Started the 90-second Owner Tour in the synthetic Owner view. No credential or company system was accessed.');}else if(workspaceRole!=='Owner'){workspaceRole='Owner';profile={...profile,role:'Owner'};log('Opened the Owner Tour in the local Owner view. No real role or account changed.');}ownerTourRoute(0);}
function ownerTourInstallLauncher(){if(!demoEntered)return;const topActions=document.querySelector('.top-actions');if(!topActions||topActions.querySelector('.owner-tour-topbar'))return;const control=document.createElement('button');control.type='button';control.className='owner-tour-topbar';control.dataset.action='start-owner-tour';control.setAttribute('aria-label','Start the 90-second Owner Tour');control.innerHTML=`${icon('play')}<span>Owner Tour</span>`;topActions.prepend(control);}
function ownerTourReturnFocus(){(document.querySelector('.owner-tour-topbar')||document.querySelector('.owner-tour-sidebar')||document.querySelector('#main'))?.focus({preventScroll:true});}
function finishOwnerTour(completed){ownerTourState.active=false;const app=document.querySelector('#app');if(app)app.inert=false;document.querySelector('#owner-tour-layer')?.remove();document.querySelectorAll('.owner-tour-target').forEach(node=>node.classList.remove('owner-tour-target'));render();requestAnimationFrame(ownerTourReturnFocus);toast(completed?'Owner Tour complete. Explore the synthetic workspace at your own pace.':'Owner Tour closed. The synthetic workspace remains available to explore.');}
function ownerTourMove(direction){const next=ownerTourState.index+direction;if(next<0||next>=ownerTourSteps.length)return;ownerTourRoute(next);}

const demoSignInBeforeOwnerTour=demoSignIn;
demoSignIn=()=>demoSignInBeforeOwnerTour().replace('<p class="demo-no-credential">',`<button class="owner-tour-entry" type="button" data-action="start-owner-tour">${icon('play')}Take the 90-second Owner Tour<span>Guided local demo · no account required</span></button><p class="demo-no-credential">`);
const sidebarBeforeOwnerTour=sidebar;
sidebar=()=>sidebarBeforeOwnerTour().replace('<button class="demo-signout"',`<button class="owner-tour-sidebar" type="button" data-action="start-owner-tour">${icon('play')}Owner Tour <span>90 sec</span></button><button class="demo-signout"`);
const renderBeforeOwnerTour=render;
render=()=>{renderBeforeOwnerTour();ownerTourInstallLauncher();if(ownerTourState.active)ownerTourMount({focus:false});else{document.querySelector('#app').inert=false;document.querySelector('#owner-tour-layer')?.remove();}};
const actionBeforeOwnerTour=action;
action=async name=>{if(name==='start-owner-tour'){startOwnerTour();return;}if(name==='tour-next'){ownerTourMove(1);return;}if(name==='tour-back'){ownerTourMove(-1);return;}if(name==='tour-skip'){finishOwnerTour(false);return;}if(name==='tour-finish'){finishOwnerTour(true);return;}return actionBeforeOwnerTour(name);};
document.addEventListener('keydown',event=>{if(!ownerTourState.active)return;if(event.key==='Escape'){event.preventDefault();event.stopImmediatePropagation();finishOwnerTour(false);return;}if(event.key==='Tab'){const controls=[...document.querySelectorAll('#owner-tour button:not([disabled])')];if(!controls.length)return;const first=controls[0],last=controls[controls.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}return;}if(!event.altKey&&!event.ctrlKey&&!event.metaKey&&event.key==='ArrowRight'){event.preventDefault();ownerTourMove(1);return;}if(!event.altKey&&!event.ctrlKey&&!event.metaKey&&event.key==='ArrowLeft'){event.preventDefault();ownerTourMove(-1);return;}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();event.stopImmediatePropagation();}},true);
render();
